        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };

        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, audit, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_log_sink(&log_sink);
