    /// With an available store, `spawn` reads the bundle off the mounted
    /// filesystem, verifies it through the shared load gate, and spawns
    /// exactly the validated `Run` image with the bundle's command name as
    /// its default argument vector (`plans/APPS.md` deliverable 8).
    #[test]
    fn spawn_of_a_verified_store_bundle_spawns_the_validated_image() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, BUNDLE_PATH);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let (memfs, anchor, run) =
            crate::test_bundle::composed_bundle(alloc::vec![CapabilityId::CONSOLE_WRITE]);
        let memfs: &'static crate::test_bundle::MemFs = Box::leak(Box::new(memfs));
        let store: &'static crate::appspawn::AppStore =
            Box::leak(Box::new(crate::appspawn::AppStore::pending(anchor)));
        store.note_available();
        let producer: &'static RecordingSpawn = Box::leak(Box::new(RecordingSpawn::new()));
        let h = spawn_handler(
            &sched,
            &table,
            &arch,
            sink,
            &irq,
            &ctl,
            &ipc,
            &aspaces,
            &rng,
            &frames,
            &EMPTY_PROGRAM_REGISTRY,
            producer,
        )
        .with_filesystem(memfs)
        .with_app_store(store);
        let pid = h
            .spawn(&ctx, 0x1000, BUNDLE_PATH.len(), 0, 0, 0, 0)
            .expect("disk-backed spawn succeeds");
        assert!(pid > 0);
        // The producer received byte-for-byte the validated on-disk image,
        // and the child's default argument vector is the bundle's command
        // name.
        assert_eq!(producer.rxe.lock().as_slice(), run.as_slice());
        assert_eq!(producer.args.lock().as_slice(), &[b"ps".to_vec()]);
        let guard = table.read();
        let record = guard
            .caps_for(SecTaskId(pid))
            .expect("child caps registered under its pid");
        // The attested name is the bundle's command stem, never the `Run`
        // leaf every bundle shares — a process listing must name the app.
        assert_eq!(record.name(), "ps");
    }

    /// A [`FilesystemService`] over the shared [`MemFs`] fixture that
    /// counts data reads and can refuse `open`, so the cache tests can
    /// prove a cached launch re-reads nothing and still authorises the
    /// caller (a refused `open` is the secured VFS denying the read).
    struct InstrumentedFs {
        inner: crate::test_bundle::MemFs,
        reads: core::sync::atomic::AtomicUsize,
        deny_open: bool,
    }

    impl InstrumentedFs {
        fn new(inner: crate::test_bundle::MemFs, deny_open: bool) -> Self {
            Self {
                inner,
                reads: core::sync::atomic::AtomicUsize::new(0),
                deny_open,
            }
        }

        fn reads(&self) -> usize {
            self.reads.load(core::sync::atomic::Ordering::Relaxed)
        }
    }

    impl crate::fs::FilesystemService for InstrumentedFs {
        fn open(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            flags: OpenFlags,
        ) -> Result<(), Errno> {
            if self.deny_open {
                return Err(Errno::PermissionDenied);
            }
            self.inner.open(uid, caps, path, flags)
        }

        fn read(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            offset: u64,
            buf: &mut [u8],
        ) -> Result<usize, Errno> {
            self.reads
                .fetch_add(1, core::sync::atomic::Ordering::Relaxed);
            self.inner.read(uid, caps, path, offset, buf)
        }

        fn write(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            offset: u64,
            append: bool,
            data: &[u8],
        ) -> Result<usize, Errno> {
            self.inner.write(uid, caps, path, offset, append, data)
        }

        fn readdir(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
        ) -> Result<alloc::vec::Vec<crate::fs::ReaddirEntry>, Errno> {
            self.inner.readdir(uid, caps, path)
        }

        fn stat(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
        ) -> Result<FileStat, Errno> {
            self.inner.stat(uid, caps, path)
        }

        fn truncate(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            size: u64,
        ) -> Result<(), Errno> {
            self.inner.truncate(uid, caps, path, size)
        }

        fn sync(&self, uid: u32, caps: &dyn rustos_abi::CapabilityQuery) -> Result<(), Errno> {
            self.inner.sync(uid, caps)
        }

        fn mkdir(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
        ) -> Result<(), Errno> {
            self.inner.mkdir(uid, caps, path)
        }

        fn unlink(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            flags: UnlinkFlags,
        ) -> Result<(), Errno> {
            self.inner.unlink(uid, caps, path, flags)
        }

        fn rename(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            src: &str,
            dst: &str,
        ) -> Result<(), Errno> {
            self.inner.rename(uid, caps, src, dst)
        }

        fn set_mode(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            mode: u32,
        ) -> Result<(), Errno> {
            self.inner.set_mode(uid, caps, path, mode)
        }

        fn attr_get(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            key: &[u8],
            value_out: &mut [u8],
        ) -> Result<usize, Errno> {
            self.inner.attr_get(uid, caps, path, key, value_out)
        }

        fn attr_set(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            key: &[u8],
            value: &[u8],
        ) -> Result<(), Errno> {
            self.inner.attr_set(uid, caps, path, key, value)
        }

        fn attr_list(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            index: u64,
            key_out: &mut [u8],
        ) -> Result<Option<usize>, Errno> {
            self.inner.attr_list(uid, caps, path, index, key_out)
        }

        fn attr_remove(
            &self,
            uid: u32,
            caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            key: &[u8],
        ) -> Result<(), Errno> {
            self.inner.attr_remove(uid, caps, path, key)
        }
    }

    /// Install a classified semantic launch cache under a gauge pinned at
    /// normal pressure, as the boot path does once the `/System` mount is
    /// published, so the cache-behaviour tests exercise admission and hits.
    fn install_launch_cache(store: &crate::appspawn::AppStore) {
        struct PlentyFree;
        impl rustos_kernel_mem::FreeMemorySource for PlentyFree {
            fn free_bytes(&self) -> usize {
                1 << 29
            }
            fn total_bytes(&self) -> usize {
                1 << 30
            }
        }
        let source: &'static PlentyFree = Box::leak(Box::new(PlentyFree));
        let pressure: &'static rustos_kernel_mem::MemoryPressure =
            Box::leak(Box::new(rustos_kernel_mem::MemoryPressure::over(source)));
        let audit: &'static crate::test_sink::TestSink =
            Box::leak(Box::new(crate::test_sink::TestSink::new()));
        store.install_reclaim(
            rustos_kernel_mem::CacheBudget::from_backing(1 << 24),
            pressure,
            audit,
        );
    }

    /// A second spawn of the same system-store bundle is served from the
    /// per-boot semantic launch cache: the same validated image is spawned
    /// with **zero** further data reads (no whole-bundle re-read, re-hash,
    /// or re-verify on the launch hot path) — the regression that made
    /// every command launch re-verify its bundle from disk.
    #[test]
    fn a_second_spawn_of_a_store_bundle_is_served_from_the_cache() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, BUNDLE_PATH);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        // The caller sits at task id 9: the two admitted children receive
        // the scheduler's low ids, which must not collide with the
        // caller's own aspace registration.
        aspaces
            .write()
            .register(SecTaskId(9), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(9, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(9),
            caps: &caps,
        };
        let (memfs, anchor, run) = crate::test_bundle::composed_bundle(alloc::vec![]);
        let fs: &'static InstrumentedFs = Box::leak(Box::new(InstrumentedFs::new(memfs, false)));
        let store: &'static crate::appspawn::AppStore =
            Box::leak(Box::new(crate::appspawn::AppStore::pending(anchor)));
        install_launch_cache(store);
        store.note_available();
        let producer: &'static RecordingSpawn = Box::leak(Box::new(RecordingSpawn::new()));
        let h = spawn_handler(
            &sched,
            &table,
            &arch,
            sink,
            &irq,
            &ctl,
            &ipc,
            &aspaces,
            &rng,
            &frames,
            &EMPTY_PROGRAM_REGISTRY,
            producer,
        )
        .with_filesystem(fs)
        .with_app_store(store);
        h.spawn(&ctx, 0x1000, BUNDLE_PATH.len(), 0, 0, 0, 0)
            .expect("first spawn verifies the bundle");
        let reads_after_first = fs.reads();
        assert!(reads_after_first > 0, "the first spawn reads the bundle");
        h.spawn(&ctx, 0x1000, BUNDLE_PATH.len(), 0, 0, 0, 0)
            .expect("second spawn serves the cache");
        assert_eq!(
            fs.reads(),
            reads_after_first,
            "a cached launch performs no data reads"
        );
        // Both spawns handed the producer the same validated image.
        assert_eq!(producer.rxe.lock().len(), 2 * run.len());
        assert_eq!(&producer.rxe.lock()[..run.len()], run.as_slice());
        assert_eq!(&producer.rxe.lock()[run.len()..], run.as_slice());
    }

    /// A cache hit never bypasses authorisation: when the secured VFS
    /// refuses the caller's read of the entry point, the cached launch is
    /// refused too and nothing is spawned.
    #[test]
    fn a_cache_hit_still_authorises_the_callers_read() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, BUNDLE_PATH);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        // The caller sits at task id 9: the two admitted children receive
        // the scheduler's low ids, which must not collide with the
        // caller's own aspace registration.
        aspaces
            .write()
            .register(SecTaskId(9), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(9, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(9),
            caps: &caps,
        };
        let (memfs, anchor, run) = crate::test_bundle::composed_bundle(alloc::vec![]);
        let fs: &'static InstrumentedFs = Box::leak(Box::new(InstrumentedFs::new(memfs, true)));
        let store: &'static crate::appspawn::AppStore =
            Box::leak(Box::new(crate::appspawn::AppStore::pending(anchor)));
        install_launch_cache(store);
        store.note_available();
        let producer: &'static RecordingSpawn = Box::leak(Box::new(RecordingSpawn::new()));
        let h = spawn_handler(
            &sched,
            &table,
            &arch,
            sink,
            &irq,
            &ctl,
            &ipc,
            &aspaces,
            &rng,
            &frames,
            &EMPTY_PROGRAM_REGISTRY,
            producer,
        )
        .with_filesystem(fs)
        .with_app_store(store);
        // The first spawn verifies and caches the bundle (its reads are
        // authorised per-file by the store's own read path).
        h.spawn(&ctx, 0x1000, BUNDLE_PATH.len(), 0, 0, 0, 0)
            .expect("first spawn verifies the bundle");
        // The second spawn hits the cache, but the secured VFS refuses the
        // caller's read of the entry point: the launch fails closed.
        assert_eq!(
            h.spawn(&ctx, 0x1000, BUNDLE_PATH.len(), 0, 0, 0, 0),
            Err(Errno::PermissionDenied)
        );
        // Only the first, verified launch reached the producer.
        assert_eq!(producer.rxe.lock().len(), run.len());
    }

    /// A tampered on-disk `Run` breaks the signed content hash and the
    /// spawn is refused with `SignatureInvalid` — nothing is launched.
    #[test]
    fn spawn_of_a_tampered_store_bundle_is_refused() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, BUNDLE_PATH);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let (mut memfs, anchor, _run) = crate::test_bundle::composed_bundle(alloc::vec![]);
        memfs
            .files
            .get_mut("/System/Apps/ps.app/Run")
            .expect("run present")
            .push(0xFF);
        let memfs: &'static crate::test_bundle::MemFs = Box::leak(Box::new(memfs));
        let store: &'static crate::appspawn::AppStore =
            Box::leak(Box::new(crate::appspawn::AppStore::pending(anchor)));
        store.note_available();
        let producer: &'static RecordingSpawn = Box::leak(Box::new(RecordingSpawn::new()));
        let h = spawn_handler(
            &sched,
            &table,
            &arch,
            sink,
            &irq,
            &ctl,
            &ipc,
            &aspaces,
            &rng,
            &frames,
            &EMPTY_PROGRAM_REGISTRY,
            producer,
        )
        .with_filesystem(memfs)
        .with_app_store(store);
        assert_eq!(
            h.spawn(&ctx, 0x1000, BUNDLE_PATH.len(), 0, 0, 0, 0),
            Err(Errno::SignatureInvalid)
        );
        assert!(producer.rxe.lock().is_empty(), "nothing may be spawned");
    }

    /// A caller-supplied startup-strings block replaces the program's
    /// registered default arguments and carries the environment verbatim:
    /// the producer receives exactly the staged, revalidated strings — a
    /// shell's typed words and exported variables reach the child.
    #[test]
    fn spawn_strings_block_overrides_registry_args_and_carries_env() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // The caller's page holds the path followed by the encoded block,
        // built by the same shared encoder userland's `spawn_with` uses.
        let args: [&[u8]; 2] = [b"man", b"ps"];
        let env: [&[u8]; 1] = [b"LANG=fr-FR"];
        let block_len = rustos_abi::process_start_encoded_len(&args, &env).expect("sized");
        let mut block = alloc::vec![0u8; block_len];
        rustos_abi::process_start_write_into(&mut block, &args, &env, 0).expect("encoded");
        let mut payload = SPAWN_PATH.to_vec();
        payload.extend_from_slice(&block);
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, &payload);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[b"registry-default"],
                },
            ])))));
        let producer: &'static RecordingSpawn = Box::leak(Box::new(RecordingSpawn::new()));
        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
            producer,
        );

        let strings_addr = 0x1000 + SPAWN_PATH.len() as u64;
        let pid = h
            .spawn(
                &ctx,
                0x1000,
                SPAWN_PATH.len(),
                0,
                0,
                strings_addr,
                block.len(),
            )
            .expect("spawn with strings succeeds");
        assert!(pid > 0);
        // The caller's block governs: the registered default argument is
        // replaced, and the environment arrives verbatim.
        assert_eq!(
            producer.args.lock().as_slice(),
            &[b"man".to_vec(), b"ps".to_vec()]
        );
        assert_eq!(producer.env.lock().as_slice(), &[b"LANG=fr-FR".to_vec()]);
    }

