    /// A present block that does not parse as a `PSV1` startup vector is
    /// rejected fail-closed before the producer is reached — never
    /// partially applied.
    #[test]
    fn spawn_malformed_strings_block_fails_closed() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // Long enough to clear the length pre-checks, but its magic is not
        // `PSV1`, so the one shared decoder refuses it.
        let bogus_block = [0u8; 64];
        let mut payload = SPAWN_PATH.to_vec();
        payload.extend_from_slice(&bogus_block);
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, &payload);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[],
                },
            ])))));
        let producer: &'static RecordingSpawn = Box::leak(Box::new(RecordingSpawn::new()));
        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
            producer,
        );

        let strings_addr = 0x1000 + SPAWN_PATH.len() as u64;
        assert_eq!(
            h.spawn(
                &ctx,
                0x1000,
                SPAWN_PATH.len(),
                0,
                0,
                strings_addr,
                bogus_block.len(),
            ),
            Err(Errno::BadMagic)
        );
        assert!(producer.rxe.lock().is_empty());
    }

    /// The strings pair's shape is validated before any state is touched:
    /// a zero address with a non-zero length, a present address with a
    /// zero length, and a length above the format's own ceiling each fail
    /// closed without reaching the producer.
    #[test]
    fn spawn_strings_shape_violations_fail_closed() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, SPAWN_PATH);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[],
                },
            ])))));
        let producer: &'static RecordingSpawn = Box::leak(Box::new(RecordingSpawn::new()));
        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
            producer,
        );

        // Zero address with a non-zero length: a contradictory pair.
        assert_eq!(
            h.spawn(&ctx, 0x1000, SPAWN_PATH.len(), 0, 0, 0, 8,),
            Err(Errno::LengthOutOfRange)
        );
        // Present address with a zero length: no decodable block.
        assert_eq!(
            h.spawn(&ctx, 0x1000, SPAWN_PATH.len(), 0, 0, 0x2000, 0,),
            Err(Errno::LengthOutOfRange)
        );
        // A length above the startup-vector format's own ceiling: bounded
        // before any kernel allocation is attempted.
        let oversized = usize::try_from(PROCESS_START_MAX_TOTAL_LEN).expect("fits") + 1;
        assert_eq!(
            h.spawn(&ctx, 0x1000, SPAWN_PATH.len(), 0, 0, 0x2000, oversized,),
            Err(Errno::LengthOutOfRange)
        );
        assert!(producer.rxe.lock().is_empty());
    }

    /// The privileged driver-spawn path mints one device-resource grant
    /// per the matched node's requested [`HwResource`] for the freshly
    /// admitted child, keyed to the child's own kernel-trusted id: the
    /// child resolves each handle (the `resource_grants` / `mmio_map`
    /// source), handles are monotonic from `1` in request order, and a
    /// different task presenting the same numeric handle resolves nothing
    /// — the registry owner-check.
    #[test]
    fn driver_spawn_mints_an_owner_checked_grant_per_requested_resource() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let frames = spawn_test_frames();

        // The matched node's two requested resources: a register window and
        // a DMA constraint. These originate kernel-side (the driver-spawn
        // path threads the discovered node's requests), never a caller.
        let regs = HwResource::mmio(0x0a00_0000, 0x1000);
        let dma = HwResource::dma(0, 0x1000);
        let requested = [regs, dma];

        // Set the arch's monotonic counter to a known value so the admit
        // path's start-time attestation (read from `ticks_now`) is observable
        // and distinguishable from the `0` boot sentinel.
        let admit_ticks: u64 = 0x4242;
        arch.set_ticks(admit_ticks);

        let ctx = KernelSpawnCtx::new(
            &frames,
            None,
            sink,
            &sched,
            &table,
            &aspaces,
            arch.as_ref(),
            SecTaskId(1),
            &NULL_PROCESS_WAIT,
            DescriptorTable::standard(),
            Vec::new(),
            &requested,
            // The matched node the driver was loaded for.
            Some(0x55),
            // A fixed minted identity so the admit path's attestation is
            // observable.
            rustos_abi::ProcId::from_raw([0x11; 16]),
            // A fixed name so the admit path's name attestation is observable.
            ProcName::from_bytes_truncating(b"driverproc"),
            // The kernel-resolved path the admit path records for a later
            // self-spawn.
            SPAWN_PATH.to_vec(),
            // A driver-spawn admits under the fixed system credential.
            SpawnCredential::system(),
            false,
        );

        let program = EmbeddedProgram {
            path: SPAWN_PATH,
            rxe: SPAWN_RXE,
            caps: &[],
            args: &[],
        };
        // `RecordingSpawn::spawn` admits a host child through
        // `ctx.admit_process`, returning the new PID the grants are minted
        // against.
        let pid = RecordingSpawn::new()
            .spawn_with(
                program.rxe,
                &ctx,
                program.capability_set(),
                program.args,
                &[],
            )
            .expect("driver child admitted");
        let child = SecTaskId(pid);

        // The minted process-instance identity is attested onto the child's
        // capability record by `admit_process`, distinct from its numeric id.
        assert_eq!(
            table.read().caps_for(child).map(TaskCapabilities::proc_id),
            Some(rustos_abi::ProcId::from_raw([0x11; 16]))
        );

        // The kernel-attested process name is threaded from the spawn context
        // onto the child's capability record by `admit_process`, so an audit
        // consumer can name the acting process.
        assert_eq!(
            table
                .read()
                .caps_for(child)
                .map(|c| alloc::string::ToString::to_string(c.name())),
            Some(alloc::string::String::from("driverproc"))
        );

        // The admit path snapshots the kernel's monotonic clock as the
        // child's attested start time — read from `ticks_now`, never
        // caller-supplied — so an audit or origin consumer can age and order
        // the instance.
        assert_eq!(
            table
                .read()
                .caps_for(child)
                .map(TaskCapabilities::start_time),
            Some(admit_ticks)
        );

        // The driver's matched node is recorded against it, so a later
        // `hw_emit_node` parents its published child under exactly this node
        // (the emitter cannot forge its position).
        assert_eq!(aspaces.read().loaded_node(child), Some(0x55));
        // A different task has no loaded node (owner-bound, fail closed).
        assert_eq!(aspaces.read().loaded_node(SecTaskId(pid + 1)), None);

        // One handle per requested resource, monotonic from 1, in order.
        assert_eq!(aspaces.read().grant(child, 1), Some(regs));
        assert_eq!(aspaces.read().grant(child, 2), Some(dma));
        // No third grant was minted.
        assert_eq!(aspaces.read().grant(child, 3), None);
        // Owner-check: a different task presenting the same handle value
        // resolves nothing — a driver cannot reach another's window by
        // guessing a handle.
        assert_eq!(aspaces.read().grant(SecTaskId(pid + 1), 1), None);

        // The set serialises for delivery through `resource_grants`: two
        // consecutive `GrantedResource` records in ascending handle order.
        let wire = aspaces.read().grants_to_le_bytes(child);
        assert_eq!(
            wire.len(),
            2 * rustos_abi::hwtree::GrantedResource::WIRE_LEN
        );
        let first =
            rustos_abi::hwtree::GrantedResource::from_bytes(&wire).expect("first record decodes");
        assert_eq!(first.handle, 1);
        assert_eq!(first.resource, regs);
        let second = rustos_abi::hwtree::GrantedResource::from_bytes(
            &wire[rustos_abi::hwtree::GrantedResource::WIRE_LEN..],
        )
        .expect("second record decodes");
        assert_eq!(second.handle, 2);
        assert_eq!(second.resource, dma);
    }

    /// The admit path attests the child's **parentage**: it reads the
    /// spawning parent's own kernel-held [`ProcId`] from the capability
    /// table and records it on the child, so parentage is authoritative and
    /// survives PID reuse. A child whose parent has no capability record (a
    /// kernel-parented admit) records the [`ProcId::KERNEL`] sentinel.
    #[test]
    fn admit_attests_the_childs_parent_proc_id_from_the_parents_record() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let frames = spawn_test_frames();

        // Register the spawning parent's own kernel-held record, carrying a
        // known attested process-instance identity distinct from its numeric
        // id. This is what the admit path must copy onto the child — never a
        // caller-supplied value.
        let parent_task = SecTaskId(3);
        let parent_proc = rustos_abi::ProcId::from_raw([0x22; 16]);
        table.write().insert(
            TaskCapabilities::derive(
                parent_task,
                UserId(0),
                CapabilitySet::empty(),
                CapabilitySet::empty(),
                sink,
            )
            .with_proc_id(parent_proc),
        );

        let program = EmbeddedProgram {
            path: SPAWN_PATH,
            rxe: SPAWN_RXE,
            caps: &[],
            args: &[],
        };

        // One ctx builder for both admits below: everything but the parent
        // and the minted child identity is the same live kernel state.
        let make_ctx = |parent: SecTaskId, proc_id: rustos_abi::ProcId| {
            KernelSpawnCtx::new(
                &frames,
                None,
                sink,
                &sched,
                &table,
                &aspaces,
                arch.as_ref(),
                parent,
                &NULL_PROCESS_WAIT,
                DescriptorTable::standard(),
                Vec::new(),
                &[],
                None,
                proc_id,
                ProcName::EMPTY,
                alloc::vec::Vec::new(),
                SpawnCredential::system(),
                false,
            )
        };

        // A child spawned by that parent records the parent's attested
        // identity as its parentage, and its own (distinct) minted identity
        // as `proc_id`.
        let child_proc = rustos_abi::ProcId::from_raw([0x11; 16]);
        let ctx = make_ctx(parent_task, child_proc);
        let pid = RecordingSpawn::new()
            .spawn_with(
                program.rxe,
                &ctx,
                program.capability_set(),
                program.args,
                &[],
            )
            .expect("child admitted");
        let child = SecTaskId(pid);
        assert_eq!(
            table.read().caps_for(child).map(TaskCapabilities::proc_id),
            Some(child_proc),
            "child carries its own minted identity"
        );
        assert_eq!(
            table
                .read()
                .caps_for(child)
                .map(TaskCapabilities::parent_proc_id),
            Some(parent_proc),
            "child records the parent's attested identity as parentage"
        );

        // A kernel-parented admit — the parent id names no capability record
        // — records the kernel sentinel, never a fabricated value.
        let orphan_ctx = make_ctx(SecTaskId(9999), rustos_abi::ProcId::from_raw([0x33; 16]));
        let orphan_pid = RecordingSpawn::new()
            .spawn_with(
                program.rxe,
                &orphan_ctx,
                program.capability_set(),
                program.args,
                &[],
            )
            .expect("kernel-parented child admitted");
        assert_eq!(
            table
                .read()
                .caps_for(SecTaskId(orphan_pid))
                .map(TaskCapabilities::parent_proc_id),
            Some(rustos_abi::ProcId::KERNEL),
            "a parent with no record yields the kernel sentinel"
        );
    }

    /// A [`ProcessSpawn`] double that records whether the [`SpawnCtx`] it
    /// is handed exposes a `'static` page-table frame allocator. It never admits a task — it returns
    /// `NotImplemented` after recording — so a test can assert the wiring
    /// without standing up an arch image build.
    struct PageTableAllocProbeSpawn {
        saw_static_allocator: core::sync::atomic::AtomicBool,
    }

    impl PageTableAllocProbeSpawn {
        fn new() -> Self {
            Self {
                saw_static_allocator: core::sync::atomic::AtomicBool::new(false),
            }
        }
    }

    impl ProcessSpawn for PageTableAllocProbeSpawn {
        fn spawn_with(
            &self,
            _rxe: &[u8],
            ctx: &dyn SpawnCtx,
            _caps: CapabilitySet,
            _args: &[&[u8]],
            _env: &[&[u8]],
        ) -> Result<u64, Errno> {
            self.saw_static_allocator.store(
                ctx.page_table_allocator().is_some(),
                core::sync::atomic::Ordering::SeqCst,
            );
            Err(Errno::NotImplemented)
        }
    }

    /// When the boot path threads a `'static` page-table allocator through
    /// [`KernelSyscallHandlers::with_page_table_frames`], the producer sees
    /// it via [`SpawnCtx::page_table_allocator`] — the seam an arch producer
    /// builds a child's page tables out of reclaimable RAM through.
    #[test]
    fn spawn_threads_the_static_page_table_allocator_to_the_producer() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, SPAWN_PATH);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        // The page-table allocator is a `'static` borrow in production; leak
        // a test one so the type matches.
        let ptf: &'static FrameAllocator = Box::leak(Box::new(spawn_test_frames()));
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[],
                },
            ])))));
        let probe: &'static PageTableAllocProbeSpawn =
            Box::leak(Box::new(PageTableAllocProbeSpawn::new()));

        // Wired: the producer must observe `Some`.
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_frames(&frames)
        .with_page_table_frames(ptf)
        .with_spawn(programs, probe);
        // The probe records and returns `NotImplemented`; the recording, not
        // the result, is what proves the wiring.
        let _ = h.spawn(&ctx, 0x1000, SPAWN_PATH.len(), 0, 0, 0, 0);
        assert!(
            probe
                .saw_static_allocator
                .load(core::sync::atomic::Ordering::SeqCst),
            "the producer must see the wired `'static` page-table allocator"
        );

        // Unwired: with no `with_page_table_frames`, the producer sees `None`
        // and an arch producer fails closed.
        probe
            .saw_static_allocator
            .store(true, core::sync::atomic::Ordering::SeqCst);
        let h2 = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs, probe,
        );
        let _ = h2.spawn(&ctx, 0x1000, SPAWN_PATH.len(), 0, 0, 0, 0);
        assert!(
            !probe
                .saw_static_allocator
                .load(core::sync::atomic::Ordering::SeqCst),
            "with no page-table allocator wired the producer must see None"
        );
    }

    /// A spawned child inherits the parent's effective resource limits,
    /// intersected against the system default so it can never widen past
    /// the parent's ceiling (inheritance across spawn).
    #[test]
    fn spawn_child_inherits_the_parents_resource_limits() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, SPAWN_PATH);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        // The parent caps its own child-process fan-out below the default.
        let parent_cap = ResourceLimit::new(2, 4).expect("well-formed");
        aspaces
            .write()
            .set_limit(SecTaskId(2), LimitKind::Processes, parent_cap);
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };

        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[],
                },
            ])))));
        let producer: &'static RecordingSpawn = Box::leak(Box::new(RecordingSpawn::new()));

        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
            producer,
        );

        let pid = h
            .spawn(&ctx, 0x1000, SPAWN_PATH.len(), 0, 0, 0, 0)
            .expect("spawn succeeds");
        // The child carries the parent's tighter Processes ceiling and the
        // default policy for every other kind.
        let child = aspaces.read().limits(SecTaskId(pid));
        assert_eq!(child.get(LimitKind::Processes), parent_cap);
        assert_eq!(
            child.get(LimitKind::StackBytes),
            LimitSet::DEFAULT.get(LimitKind::StackBytes)
        );
    }

    /// The spawn admit path records the new child against the spawning
    /// caller (the parent) with the process-wait producer, so a later `wait`
    /// from that parent can reap it (`plans/SPAWN.md` SP6).
    #[test]
    fn spawn_admit_registers_child_with_process_wait_producer() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, SPAWN_PATH);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };

        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[],
                },
            ])))));
        let producer: &'static RecordingSpawn = Box::leak(Box::new(RecordingSpawn::new()));
        let wait_producer: &'static RecordingProcessWait = Box::leak(Box::new(
            RecordingProcessWait::new(Ok(crate::procwait::WaitedChild {
                pid: 0,
                status: rustos_abi::WaitStatus::Exited(0),
            })),
        ));

        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
            producer,
        )
        .with_process_wait(wait_producer);

        let pid = h
            .spawn(&ctx, 0x1000, SPAWN_PATH.len(), 0, 0, 0, 0)
            .expect("spawn succeeds");
        // The child (its returned PID) was registered against parent 2.
        assert_eq!(*wait_producer.last_register.lock(), Some((2, pid)));
    }

