    /// A test [`HwTreeSource`] holding a fixed generation, a pre-encoded
    /// snapshot blob, and a record of every node published through
    /// [`HwTreeSource::publish`] so a `hw_emit_node` test can assert what
    /// reached the store.
    struct StaticHwTree {
        generation: u64,
        blob: alloc::vec::Vec<u8>,
        published: RwLock<alloc::vec::Vec<(u32, rustos_abi::HwNode)>>,
        // Every `(parent_id, node_id)` removed through `HwTreeSource::remove`,
        // so a `hw_remove_node` test can assert what the handler passed.
        removed: RwLock<alloc::vec::Vec<(u32, u32)>>,
        // Node ids this double rejects with `NotFound` (a node the caller does
        // not own / an absent node), so a test can drive the fail-closed arm.
        unremovable: RwLock<alloc::vec::Vec<u32>>,
    }

    impl StaticHwTree {
        fn new(generation: u64, blob: alloc::vec::Vec<u8>) -> Self {
            Self {
                generation,
                blob,
                published: RwLock::new(alloc::vec::Vec::new()),
                removed: RwLock::new(alloc::vec::Vec::new()),
                unremovable: RwLock::new(alloc::vec::Vec::new()),
            }
        }
    }

    impl HwTreeSource for StaticHwTree {
        fn generation(&self) -> Result<u64, Errno> {
            Ok(self.generation)
        }
        fn snapshot(&self) -> Result<alloc::vec::Vec<u8>, Errno> {
            Ok(self.blob.clone())
        }
        fn publish(&self, parent_id: u32, node: rustos_abi::HwNode) -> Result<u32, Errno> {
            // Record the kernel-resolved parent the handler passed alongside
            // the node, so a test can assert the child is parented under the
            // emitter's own loaded node. Model the real store's identity
            // assignment with a deterministic id (a fixed base plus the
            // publish count) so the handler's id-return path is exercised.
            let id = 100u32 + u32::try_from(self.published.read().len()).unwrap_or(0);
            self.published.write().push((parent_id, node));
            Ok(id)
        }
        fn remove(&self, parent_id: u32, node_id: u32) -> Result<alloc::vec::Vec<u32>, Errno> {
            // Model the store's fail-closed ownership gate: a node listed as
            // unremovable (unknown / not owned by the caller) is `NotFound`
            // and is never recorded as removed. A successful removal reports
            // the single removed id, as the real store reports the subtree.
            if self.unremovable.read().contains(&node_id) {
                return Err(Errno::NotFound);
            }
            self.removed.write().push((parent_id, node_id));
            Ok(alloc::vec![node_id])
        }
    }

    /// Build a wire-encoded `[HwTreeHeader][HwNode; n]` snapshot at
    /// `generation` from `nodes`, exactly as the production source does.
    fn encode_hw_snapshot(generation: u64, nodes: &[rustos_abi::HwNode]) -> alloc::vec::Vec<u8> {
        let header = rustos_abi::HwTreeHeader::new(generation, nodes.len() as u64).to_le_bytes();
        let mut blob = alloc::vec::Vec::with_capacity(header.len() + nodes.len() * 572);
        blob.extend_from_slice(&header);
        for node in nodes {
            blob.extend_from_slice(&node.to_le_bytes());
        }
        blob
    }

    /// A test double for the introspection source: it hands back fixed
    /// encoded bytes per domain (or a configurable error) so the handler's
    /// paging, copy-out, and fail-closed arms can be driven without a live
    /// `CapTable`/scheduler.
    struct StaticIntrospect {
        processes: alloc::vec::Vec<u8>,
        kernel_memory: alloc::vec::Vec<u8>,
        limits: Result<alloc::vec::Vec<u8>, Errno>,
        /// Records the `(offset, max_records)` the handler passed, so a test
        /// can assert the record-granular paging arithmetic.
        processes_call: RwLock<Option<(u64, usize)>>,
        /// Records the `ProcId` the handler resolved for a `TaskLimits` query.
        limits_call: RwLock<Option<ProcId>>,
    }

    impl crate::introspect::IntrospectSource for StaticIntrospect {
        fn processes(&self, offset: u64, max_records: usize) -> Result<alloc::vec::Vec<u8>, Errno> {
            *self.processes_call.write() = Some((offset, max_records));
            Ok(self.processes.clone())
        }
        fn kernel_memory(&self) -> Result<alloc::vec::Vec<u8>, Errno> {
            Ok(self.kernel_memory.clone())
        }
        fn mounts(&self, _offset: u64, _max_records: usize) -> Result<alloc::vec::Vec<u8>, Errno> {
            Ok(alloc::vec::Vec::new())
        }
        fn identity(&self) -> Result<alloc::vec::Vec<u8>, Errno> {
            Err(Errno::NotImplemented)
        }
        fn uptime(&self) -> Result<alloc::vec::Vec<u8>, Errno> {
            Err(Errno::NotImplemented)
        }
        fn load_average(&self) -> Result<alloc::vec::Vec<u8>, Errno> {
            Err(Errno::NotImplemented)
        }
        fn task_limits(&self, proc_id: ProcId) -> Result<alloc::vec::Vec<u8>, Errno> {
            *self.limits_call.write() = Some(proc_id);
            self.limits.clone()
        }
        fn user_directory(
            &self,
            _offset: u64,
            _max_records: usize,
        ) -> Result<alloc::vec::Vec<u8>, Errno> {
            Ok(alloc::vec::Vec::new())
        }
        fn cpu_times(
            &self,
            _offset: u64,
            _max_records: usize,
        ) -> Result<alloc::vec::Vec<u8>, Errno> {
            Ok(alloc::vec::Vec::new())
        }
        fn memory_pressure(&self) -> Result<alloc::vec::Vec<u8>, Errno> {
            Err(Errno::NotImplemented)
        }
        fn reclaim(&self, _offset: u64, _max_records: usize) -> Result<alloc::vec::Vec<u8>, Errno> {
            Ok(alloc::vec::Vec::new())
        }
        fn ramzip(&self) -> Result<alloc::vec::Vec<u8>, Errno> {
            Err(Errno::NotImplemented)
        }
        fn cpu_load(
            &self,
            _offset: u64,
            _max_records: usize,
        ) -> Result<alloc::vec::Vec<u8>, Errno> {
            Ok(alloc::vec::Vec::new())
        }
    }

    /// `sysinfo_introspect` copies the process window out to the caller,
    /// caps the record count to what fits the buffer, and returns the exact
    /// byte length.
    #[test]
    fn sysinfo_introspect_processes_copies_out_and_pages_by_record() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::WRITE | MapFlags::USER, &[]);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::SYSINFO_INTROSPECT], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };

        let rec = ProcessRecord::new(
            1,
            0,
            ProcId::KERNEL,
            ProcId::KERNEL,
            0,
            0,
            rustos_abi::sysinfo::ProcessState::Running,
            0,
            0,
            0,
            b"init",
        )
        .expect("record");
        let blob = rec.to_le_bytes().to_vec();
        let source: &'static StaticIntrospect = Box::leak(Box::new(StaticIntrospect {
            processes: blob.clone(),
            kernel_memory: alloc::vec::Vec::new(),
            limits: Ok(alloc::vec::Vec::new()),
            processes_call: RwLock::new(None),
            limits_call: RwLock::new(None),
        }));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_introspect(source);

        // Domain 0 = Processes, arg 5 = record offset, 4096-byte buffer.
        assert_eq!(
            h.sysinfo_introspect(&ctx, IntrospectDomain::Processes.as_u32(), 5, 0x1000, 4096),
            Ok(blob.len() as u64)
        );
        // The handler forwarded the offset and capped the record count to
        // what the buffer holds.
        assert_eq!(
            *source.processes_call.read(),
            Some((5, 4096 / ProcessRecord::WIRE_LEN))
        );
        let delivered = h
            .with_caller_aspace(&ctx, |space, physmap| {
                let mut buf = alloc::vec![0u8; blob.len()];
                copy_in(space, physmap, VirtAddr::new(0x1000), &mut buf).expect("readable");
                buf
            })
            .expect("caller has a registered space");
        assert_eq!(delivered, blob);
    }

    /// A buffer too small to hold even one process record fails closed with
    /// `BufferTooSmall` before the source is touched.
    #[test]
    fn sysinfo_introspect_undersized_process_buffer_fails_closed() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::SYSINFO_INTROSPECT], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let source: &'static StaticIntrospect = Box::leak(Box::new(StaticIntrospect {
            processes: alloc::vec::Vec::new(),
            kernel_memory: alloc::vec::Vec::new(),
            limits: Ok(alloc::vec::Vec::new()),
            processes_call: RwLock::new(None),
            limits_call: RwLock::new(None),
        }));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_introspect(source);
        assert_eq!(
            h.sysinfo_introspect(&ctx, IntrospectDomain::Processes.as_u32(), 0, 0x1000, 8),
            Err(Errno::BufferTooSmall)
        );
        // The source was never consulted (fail closed before touching state).
        assert_eq!(*source.processes_call.read(), None);
    }

