    /// `ipc_call` against a restricted-sender endpoint the caller lacks the
    /// send capability for fails closed with `PermissionDenied` at post
    /// time — after the request copy-in, before any reply.
    #[test]
    fn ipc_call_without_send_capability_is_permission_denied() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = call_aspace(b"ping");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[], sink); // lacks NET_RAW
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };

        // A restricted-sender endpoint requiring NET_RAW; its creator holds
        // IPC_BIND_PRIVILEGED (required to bind a restricted endpoint).
        let id = 0xCA11_1003;
        let binder = make_caps_record(
            1,
            &[CapabilityId::IPC_BIND_PRIVILEGED, CapabilityId::NET_RAW],
            sink,
        );
        let ep = Arc::new(
            CallEndpoint::create(
                EndpointId(id),
                &binder,
                caps_with(&[CapabilityId::NET_RAW]),
                CapabilitySet::empty(),
                CallEndpointLimits {
                    max_request: 128,
                    max_reply: 128,
                    capacity: 4,
                },
                sink,
            )
            .expect("restricted endpoint"),
        );
        crate::callreg::register(ep, sink).expect("registered");

        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        assert_eq!(
            h.ipc_call(&ctx, id, 0x1000, 4, 0x2000, 64),
            Err(Errno::PermissionDenied)
        );
        crate::callreg::unregister(EndpointId(id));
    }

    /// End-to-end: `ipc_call` posts the request, parks the caller, and —
    /// once a server drains the call and replies — copies the reply out to
    /// the caller's buffer and returns its length. A background thread
    /// plays the server so the parked caller is woken with a real reply.
    #[test]
    fn ipc_call_round_trips_request_and_reply() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        // A live scheduler task so the park loop's cooperative-yield
        // fallback returns `InvalidState` (the task is Ready, not Running)
        // and keeps polling, rather than `NoSuchTask`.
        let tid = sched
            .spawn(0, Priority::Normal, |_| TaskAction::Exit)
            .expect("spawn caller task");
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = call_aspace(b"ping");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(tid), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(tid, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(tid),
            caps: &caps,
        };

        let id = 0xCA11_2001;
        let ep = register_call_endpoint(id, sink);

        // The server: drain the one posted call and answer it.
        let server_ep = ep.clone();
        let handle = std::thread::spawn(move || loop {
            if let RecvCall::Received(call) = server_ep.recv_call(usize::MAX) {
                assert_eq!(call.request, b"ping");
                server_ep
                    .reply(call.ticket, b"pong", &TestSink::new())
                    .expect("reply");
                break;
            }
            std::thread::yield_now();
        });

        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        let written = h
            .ipc_call(&ctx, id, 0x1000, 4, 0x2000, 64)
            .expect("call completes");
        handle.join().expect("server thread joins");
        assert_eq!(written, 4);

        // The reply landed in the caller's page-2 buffer.
        let guard = aspaces.read();
        let (_space, physmap) = guard.resolve(SecTaskId(tid)).expect("aspace present");
        assert_eq!(read_reply_page(physmap, 4), b"pong");
        crate::callreg::unregister(EndpointId(id));
    }

    /// A reply larger than the caller's buffer fails closed with
    /// `BufferTooSmall` rather than truncating.
    #[test]
    fn ipc_call_reply_larger_than_buffer_is_buffer_too_small() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let tid = sched
            .spawn(0, Priority::Normal, |_| TaskAction::Exit)
            .expect("spawn caller task");
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = call_aspace(b"ping");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(tid), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(tid, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(tid),
            caps: &caps,
        };

        let id = 0xCA11_2002;
        let ep = register_call_endpoint(id, sink);
        let server_ep = ep.clone();
        let handle = std::thread::spawn(move || loop {
            if let RecvCall::Received(call) = server_ep.recv_call(usize::MAX) {
                server_ep
                    .reply(call.ticket, b"a long reply", &TestSink::new())
                    .expect("reply");
                break;
            }
            std::thread::yield_now();
        });

        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        // The reply is 12 bytes; the caller offers only 4.
        let result = h.ipc_call(&ctx, id, 0x1000, 4, 0x2000, 4);
        handle.join().expect("server thread joins");
        assert_eq!(result, Err(Errno::BufferTooSmall));
        crate::callreg::unregister(EndpointId(id));
    }

    // ---- call_create / call_recv / call_reply (server side) ----------

    /// First frame of the three-page server address space the `call_recv` /
    /// `call_reply` tests use: page 1 (`0x1000`) receives the request, page 2
    /// (`0x2000`) receives the ticket, page 3 (`0x3000`) holds the reply
    /// payload. Disjoint from [`CALL_FRAME`].
    const SERVER_FRAME: usize = 30;

    /// Build a server address space mapping pages 1–3 (`0x1000`/`0x2000`/
    /// `0x3000`) `RW|USER` onto three contiguous frames, seeding `reply` at
    /// the start of page 3 (the buffer `call_reply` reads from).
    fn server_aspace(
        reply: &[u8],
    ) -> (
        Box<dyn UserAddressSpace + Send + Sync>,
        Box<dyn PhysMap + Send + Sync>,
    ) {
        let base = PhysAddr::new(SERVER_FRAME as u64 * PAGE_SIZE as u64);
        let sim = SimPhysMap::new(base, PAGE_SIZE * 3);
        if !reply.is_empty() {
            let reply_base = PhysAddr::new((SERVER_FRAME as u64 + 2) * PAGE_SIZE as u64);
            let ptr = sim.translate(reply_base, reply.len()).expect("seed reply");
            // SAFETY: the window owns these bytes for the simulator's lifetime
            // and nothing else aliases them during the test.
            unsafe {
                core::ptr::copy_nonoverlapping(reply.as_ptr(), ptr.as_ptr(), reply.len());
            }
        }
        let mut space = AddressSpace::new(HostPageTable::new());
        for p in 0usize..3 {
            space
                .map(
                    page(1 + p as u64),
                    Frame(SERVER_FRAME + p),
                    MapFlags::READ | MapFlags::WRITE | MapFlags::USER,
                )
                .expect("map server page");
        }
        (Box::new(space), Box::new(sim))
    }

    /// Read `len` bytes the handler copied to page `n` (1-based) of a
    /// [`server_aspace`].
    fn read_server_page(physmap: &dyn PhysMap, n: usize, len: usize) -> alloc::vec::Vec<u8> {
        let base = PhysAddr::new((SERVER_FRAME as u64 + (n as u64 - 1)) * PAGE_SIZE as u64);
        let ptr = physmap.translate(base, len).expect("server window");
        let mut out = alloc::vec![0u8; len];
        // SAFETY: the window owns these bytes for the simulator's lifetime and
        // the handler has finished writing them.
        unsafe {
            core::ptr::copy_nonoverlapping(ptr.as_ptr(), out.as_mut_ptr(), len);
        }
        out
    }

    /// `call_create` binds an unrestricted endpoint the `ipc_call` handler can
    /// then resolve, and refuses to re-point a live id.
    #[test]
    fn call_create_registers_a_resolvable_endpoint_and_refuses_a_clash() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // Pages 1 and 2 are the (empty) send/recv `CapabilitySet` wire images.
        let (space, physmap) = call_aspace(&[0u8; CapabilitySet::WIRE_LEN]);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(5), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(5, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(5),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        let id = 0xCA11_3001;
        assert!(!crate::callreg::contains(EndpointId(id)));
        assert_eq!(h.call_create(&ctx, id, 0x1000, 0x2000, 64, 64, 4), Ok(0));
        assert!(crate::callreg::contains(EndpointId(id)));
        let denied = rustos_kernel_ipc::AuditEvent::CallEndpointRegisterDenied
            .id()
            .0;
        assert!(
            !sink.event_ids().contains(&denied),
            "a clean bind emits no register-denied audit"
        );
        // A second bind of the same live id fails closed, and the refusal —
        // not a bare "endpoint created" — is what lands on the audit trail.
        assert_eq!(
            h.call_create(&ctx, id, 0x1000, 0x2000, 64, 64, 4),
            Err(Errno::AlreadyExists)
        );
        assert!(
            sink.event_ids().contains(&denied),
            "the refused re-bind is audited as register-denied"
        );
        crate::callreg::unregister(EndpointId(id));
    }

    /// Binding the seat-scoped window rendezvous (`WINDOW_ENDPOINT`) is
    /// authorised by the kernel-attested live seat lease and nothing else
    /// for an unprivileged caller: refused before the lease exists, allowed
    /// while the caller holds it, and refused again once the lease is
    /// released (fail closed on loss). The attestation is resolved from the
    /// seat registry against the kernel-trusted caller id, never a claim.
    #[test]
    fn call_create_window_endpoint_binds_only_for_the_live_seat_lease_holder() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // Pages 1 and 2 are the (empty) send/recv `CapabilitySet` wire images.
        let (space, physmap) = call_aspace(&[0u8; CapabilitySet::WIRE_LEN]);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(0x5709), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        // An ordinary session process: no `CAP_IPC_BIND_PRIVILEGED`.
        let caps = make_caps_record(0x5709, &[CapabilityId::DISPLAY], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(0x5709),
            caps: &caps,
        };
        let queue: &'static crate::console::ConsoleInputQueue =
            Box::leak(Box::new(crate::console::ConsoleInputQueue::new()));
        let seat: &'static SeatRegistry = Box::leak(Box::new(SeatRegistry::new(queue)));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_seat_registry(seat);

        let id = rustos_abi::window_ipc::WINDOW_ENDPOINT;
        // No lease yet: the reserved id stays privileged and the bind is
        // refused with nothing registered.
        assert_eq!(
            h.call_create(&ctx, id, 0x1000, 0x2000, 64, 64, 4),
            Err(Errno::PermissionDenied)
        );
        assert!(!crate::callreg::contains(EndpointId(id)));

        // Holding the boot seat's live lease authorises the bind.
        assert!(h.display_acquire(&ctx, SEAT_PRIMARY).is_ok());
        assert_eq!(h.call_create(&ctx, id, 0x1000, 0x2000, 64, 64, 4), Ok(0));
        assert!(crate::callreg::contains(EndpointId(id)));
        crate::callreg::unregister(EndpointId(id));

        // A released lease withdraws the authority (fail closed on loss).
        assert!(h.display_release(&ctx, SEAT_PRIMARY).is_ok());
        assert_eq!(
            h.call_create(&ctx, id, 0x1000, 0x2000, 64, 64, 4),
            Err(Errno::PermissionDenied)
        );
        assert!(!crate::callreg::contains(EndpointId(id)));
    }

    /// Wire image of a one-capability send set, for seeding a `call_create`
    /// request page.
    fn one_cap_image(cap: CapabilityId) -> [u8; CapabilitySet::WIRE_LEN] {
        let mut set = CapabilitySet::empty();
        set.insert(cap);
        set.to_le_bytes()
    }

    /// Creating a grant-restricted endpoint (its required send capability is
    /// `CAP_IPC_ENDPOINT`) mints the creator the matching per-endpoint grant,
    /// so it may forward the endpoint onto a node it publishes and the
    /// autoloaded class driver inherits it — exactly as `msi_alloc` grants an
    /// allocated IRQ line.
    #[test]
    fn call_create_grant_restricted_mints_the_endpoint_grant() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // Page 1 is the send-set image {CAP_IPC_ENDPOINT}; page 2 (recv) is
        // the zeroed empty set.
        let (space, physmap) = call_aspace(&one_cap_image(CapabilityId::IPC_ENDPOINT));
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(5), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        // A restricted-sender endpoint requires CAP_IPC_BIND_PRIVILEGED to bind.
        let caps = make_caps_record(5, &[CapabilityId::IPC_BIND_PRIVILEGED], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(5),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        let id = 0xCA11_4001;
        // No grant for the endpoint before creation.
        assert!(!aspaces
            .read()
            .grant_covers(SecTaskId(5), &rustos_abi::HwResource::endpoint(id)));
        assert_eq!(h.call_create(&ctx, id, 0x1000, 0x2000, 64, 64, 4), Ok(0));
        // The creator now holds the per-endpoint grant for exactly this id.
        assert!(aspaces
            .read()
            .grant_covers(SecTaskId(5), &rustos_abi::HwResource::endpoint(id)));
        // …and not for a neighbouring id (the grant is scoped to one endpoint).
        assert!(!aspaces
            .read()
            .grant_covers(SecTaskId(5), &rustos_abi::HwResource::endpoint(id + 1)));
        crate::callreg::unregister(EndpointId(id));
    }

    /// Register a grant-restricted endpoint (required send cap
    /// `CAP_IPC_ENDPOINT`) owned by task 1, returning it for unregistration.
    fn register_grant_restricted_endpoint(id: u64, sink: &(dyn Sink + Sync)) -> Arc<CallEndpoint> {
        let creator = make_caps_record(1, &[CapabilityId::IPC_BIND_PRIVILEGED], sink);
        let mut send = CapabilitySet::empty();
        send.insert(CapabilityId::IPC_ENDPOINT);
        let ep = Arc::new(
            CallEndpoint::create(
                EndpointId(id),
                &creator,
                send,
                CapabilitySet::empty(),
                CallEndpointLimits {
                    max_request: 128,
                    max_reply: 128,
                    capacity: 4,
                },
                sink,
            )
            .expect("grant-restricted endpoint"),
        );
        crate::callreg::register(ep.clone(), sink).expect("registered");
        ep
    }

    /// `ipc_call` to a grant-restricted endpoint by a caller that holds the
    /// class capability but **not** the per-endpoint grant fails closed with
    /// `PermissionDenied`, before any buffer is copied — so one class driver
    /// cannot reach another's transport endpoint.
    #[test]
    fn ipc_call_grant_restricted_without_grant_is_permission_denied() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        // Caller holds the class capability but was never granted the endpoint.
        let caps = make_caps_record(2, &[CapabilityId::IPC_ENDPOINT], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let id = 0xCA11_4002;
        let _ep = register_grant_restricted_endpoint(id, sink);
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        assert_eq!(
            h.ipc_call(&ctx, id, 0x1000, 4, 0x2000, 64),
            Err(Errno::PermissionDenied)
        );
        crate::callreg::unregister(EndpointId(id));
    }

    /// `ipc_call` to a grant-restricted endpoint by a caller that holds both
    /// the class capability and the per-endpoint grant round-trips normally —
    /// the grant is exactly what the autoloaded class driver inherits from its
    /// matched node.
    #[test]
    fn ipc_call_grant_restricted_with_grant_round_trips() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let tid = sched
            .spawn(0, Priority::Normal, |_| TaskAction::Exit)
            .expect("spawn caller task");
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = call_aspace(b"ping");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(tid), space, physmap)
            .expect("registration succeeds");
        let id = 0xCA11_4003;
        // The caller was granted exactly this endpoint (as an autoloaded class
        // driver would inherit it from its matched node).
        aspaces
            .write()
            .mint_grant(SecTaskId(tid), rustos_abi::HwResource::endpoint(id));
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(tid, &[CapabilityId::IPC_ENDPOINT], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(tid),
            caps: &caps,
        };
        let ep = register_grant_restricted_endpoint(id, sink);
        let server_ep = ep.clone();
        let handle = std::thread::spawn(move || loop {
            if let RecvCall::Received(call) = server_ep.recv_call(usize::MAX) {
                assert_eq!(call.request, b"ping");
                server_ep
                    .reply(call.ticket, b"pong", &TestSink::new())
                    .expect("reply");
                break;
            }
            std::thread::yield_now();
        });
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        let written = h
            .ipc_call(&ctx, id, 0x1000, 4, 0x2000, 64)
            .expect("granted call completes");
        handle.join().expect("server thread joins");
        assert_eq!(written, 4);
        crate::callreg::unregister(EndpointId(id));
    }

    /// A recording [`crate::devres::SharedMemFacility`] double: it hands out
    /// a fixed physical base + VA and records the calls, so a handler test can
    /// assert `shm_create` mapped and granted without wiring a real
    /// `kernel/mem` producer or a published live space.
    struct RecordingSharedFacility {
        va: u64,
    }
    impl crate::devres::SharedMemFacility for RecordingSharedFacility {
        fn alloc_region(&self, _pages: u64) -> Result<(u64, u32), Errno> {
            Ok((0xAB00_0000, 0))
        }
        fn map_region(&self, _phys_base: u64, _pages: u64) -> Result<u64, Errno> {
            Ok(self.va)
        }
        fn unmap_region(&self, _base: u64, _len: usize) -> Result<(), Errno> {
            Ok(())
        }
        fn free_region(&self, _phys_base: u64, _order: u32, _pages: u64) {}
    }

    /// `shm_create` maps the region into the caller, mints the caller the
    /// per-region `HwResource::shared(id)` grant (so it can forward it onto a
    /// node it publishes), and writes the kernel-minted id out to `id_out`.
    #[test]
    fn shm_create_mints_the_region_grant_and_writes_the_id() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // A two-page caller space; `id_out` is page 2 (`0x2000`) so the test
        // reads the written id back with `read_reply_page`.
        let (space, physmap) = call_aspace(b"");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(7), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(7, &[CapabilityId::SHM], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(7),
            caps: &caps,
        };
        let facility: &'static RecordingSharedFacility =
            Box::leak(Box::new(RecordingSharedFacility { va: 0x2_0000_1000 }));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_shared_mem_facility(facility);

        let va = h
            .shm_create(&ctx, 4096, 0x2000)
            .expect("shm_create succeeds");
        assert_eq!(
            va, 0x2_0000_1000,
            "the mapped base flows back to the caller"
        );
        // The kernel-minted region id was written to `id_out` (page 2).
        let id_bytes = read_reply_page(
            aspaces.read().resolve(SecTaskId(7)).expect("registered").1,
            8,
        );
        let id = u64::from_le_bytes(id_bytes.try_into().expect("8 bytes"));
        // The caller now holds the per-region grant for exactly that id, so it
        // can forward the region onto a node it emits; a neighbouring id is
        // not covered (the grant is scoped to one region).
        assert!(aspaces
            .read()
            .grant_covers(SecTaskId(7), &rustos_abi::HwResource::shared(id)));
        assert!(!aspaces
            .read()
            .grant_covers(SecTaskId(7), &rustos_abi::HwResource::shared(id + 1)));
        // Cleanup so the global region registry does not leak across tests.
        let _ = crate::sharedreg::unmap(facility, SecTaskId(7), va);
    }

    /// `shm_map` fails closed for a forged handle (`NotFound`) and for a grant
    /// of the wrong kind (`OutOfRange`) before mapping anything.
    #[test]
    fn shm_map_fails_closed_for_forged_and_wrong_kind_grants() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // No registered aspace needed: both failures are decided from the
        // grant table before any region is mapped or any buffer touched.
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(8, &[CapabilityId::SHM], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(8),
            caps: &caps,
        };
        let facility: &'static RecordingSharedFacility =
            Box::leak(Box::new(RecordingSharedFacility { va: 0x2_0000_2000 }));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_shared_mem_facility(facility);

        // A handle the task was never granted resolves to nothing. Both
        // refusals are decided before the mapping (and before the `len_out`
        // write), so no user pointer is needed.
        assert_eq!(h.shm_map(&ctx, 0x9999, 0x2000), Err(Errno::NotFound));
        // A grant of the wrong kind (an IRQ line) is refused before mapping.
        let handle = aspaces
            .write()
            .mint_grant(SecTaskId(8), rustos_abi::HwResource::irq(33, 1));
        assert_eq!(h.shm_map(&ctx, handle, 0x2000), Err(Errno::OutOfRange));
    }

    /// `shm_map` maps a granted region into the caller and writes the
    /// region's byte length — the registry's own record, never the granting
    /// task's claim — to `len_out` (`plans/DISPLAY.md` D7b).
    #[test]
    fn shm_map_returns_the_base_and_reports_the_kernel_recorded_length() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // A two-page caller space; `len_out` is page 2 (`0x2000`) so the
        // test reads the written length back with `read_reply_page`.
        let (space, physmap) = call_aspace(b"");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(9), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(9, &[CapabilityId::SHM], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(9),
            caps: &caps,
        };
        let facility: &'static RecordingSharedFacility =
            Box::leak(Box::new(RecordingSharedFacility { va: 0x2_0000_3000 }));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_shared_mem_facility(facility);

        // A two-page region another task created; the caller was granted it.
        let (owner_va, id) =
            crate::sharedreg::create(facility, SecTaskId(10), 2).expect("region created");
        let handle = aspaces
            .write()
            .mint_grant(SecTaskId(9), rustos_abi::HwResource::shared(id));

        let va = h.shm_map(&ctx, handle, 0x2000).expect("shm_map succeeds");
        assert_eq!(va, 0x2_0000_3000, "the mapped base flows back");
        // The region's byte length — two whole pages, the registry's own
        // record — was written to `len_out` (page 2).
        let len_bytes = read_reply_page(
            aspaces.read().resolve(SecTaskId(9)).expect("registered").1,
            8,
        );
        let len = u64::from_le_bytes(len_bytes.try_into().expect("8 bytes"));
        assert_eq!(len, 2 * PAGE_SIZE as u64);
        // Cleanup so the global region registry does not leak across tests.
        let _ = crate::sharedreg::unmap(facility, SecTaskId(9), va);
        let _ = crate::sharedreg::unmap(facility, SecTaskId(10), owner_va);
    }

    /// `shm_grant` delegates a mapping right only for a region the caller
    /// itself holds, only to the live serving task of a real endpoint, and
    /// the minted handle resolves only for that recipient
    /// (`plans/DISPLAY.md` D7a).
    #[test]
    fn shm_grant_delegates_only_a_held_region_to_the_endpoints_server() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(7, &[CapabilityId::SHM], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(7),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        // A region the caller holds no grant for is refused before any
        // endpoint state is read — indistinguishable from a region that
        // does not exist.
        assert_eq!(h.shm_grant(&ctx, 42, 0xD15_2001), Err(Errno::NotFound));

        // The caller now holds the region's grant, but the endpoint is
        // unknown: still refused, nothing minted.
        let _own = aspaces
            .write()
            .mint_grant(SecTaskId(7), rustos_abi::HwResource::shared(42));
        assert_eq!(h.shm_grant(&ctx, 42, 0xD15_2001), Err(Errno::NotFound));

        // A live endpoint owned by the service task: the grant lands on the
        // endpoint's *server*, resolved kernel-side at grant time.
        let server_caps = make_caps_record(0x5707, &[], sink);
        let id = 0xD15_2001;
        let ep = Arc::new(
            CallEndpoint::create(
                EndpointId(id),
                &server_caps,
                CapabilitySet::empty(),
                CapabilitySet::empty(),
                CallEndpointLimits {
                    max_request: 64,
                    max_reply: 64,
                    capacity: 4,
                },
                sink,
            )
            .expect("unrestricted endpoint"),
        );
        crate::callreg::register(ep.clone(), sink).expect("registered");
        let handle = h.shm_grant(&ctx, 42, id).expect("grant mints a handle");
        // The recipient resolves it to exactly the shared region…
        assert_eq!(
            aspaces.read().grant(SecTaskId(0x5707), handle),
            Some(rustos_abi::HwResource::shared(42))
        );
        // …and the handle is meaningless when presented by anyone else
        // (owner-checked at `shm_map`; the number is useless to a bystander).
        assert_eq!(aspaces.read().grant(SecTaskId(9), handle), None);
        crate::callreg::unregister(EndpointId(id));
    }

    /// `fd_grant` delegates only a descriptor the caller itself holds, only
    /// a plain read-only, non-directory filesystem backing, and only to a
    /// live recipient task (`plans/CAPABILITY_USE.md` CU6).
    #[test]
    fn fd_grant_delegates_only_a_held_readonly_path_descriptor() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, b"/f");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let fs: &'static RecordingFs = Box::leak(Box::new(RecordingFs::new()));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_filesystem(fs);

        // An unopened descriptor is refused before any state is read.
        assert_eq!(h.fd_grant(&ctx, 99, 3), Err(Errno::NotFound));

        // A writable descriptor is outside the read-only delegation
        // surface, as is a directory handle and a pipe end.
        let wo = u32::try_from(
            h.fs_open(&ctx, 0x1000, "/f".len(), OpenFlags::WRITE)
                .expect("open write-only"),
        )
        .unwrap();
        assert_eq!(h.fd_grant(&ctx, wo, 3), Err(Errno::OutOfRange));
        let dir = u32::try_from(
            h.fs_open(
                &ctx,
                0x1000,
                "/f".len(),
                OpenFlags::READ.union(OpenFlags::DIRECTORY),
            )
            .expect("open directory"),
        )
        .unwrap();
        assert_eq!(h.fd_grant(&ctx, dir, 3), Err(Errno::OutOfRange));
        let (pipe_read, _pipe_write) = aspaces
            .write()
            .open_pipe(SecTaskId(2))
            .expect("pipe allocates");
        assert_eq!(h.fd_grant(&ctx, pipe_read, 3), Err(Errno::OutOfRange));

        // A read-only file descriptor delegates — but only to a live
        // recipient task; an unknown pid is the same `NotFound` as an
        // unopened descriptor.
        let fd = u32::try_from(
            h.fs_open(&ctx, 0x1000, "/f".len(), OpenFlags::READ)
                .expect("open read-only"),
        )
        .unwrap();
        assert_eq!(h.fd_grant(&ctx, fd, 99), Err(Errno::NotFound));
        let (rspace, rphysmap) = send_aspace(MapFlags::READ | MapFlags::USER, b"");
        aspaces
            .write()
            .register(SecTaskId(3), rspace, rphysmap)
            .expect("recipient registers");
        let handle = h.fd_grant(&ctx, fd, 3).expect("grant mints a handle");
        assert!(handle >= 1, "handle 0 is the reserved invalid value");
    }

    /// An `fd_grant` handle redeems only for the recipient it was minted
    /// to, exactly once, into a read-only delegated descriptor.
    #[test]
    fn fd_redeem_is_owner_bound_and_one_shot() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, b"/f");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let (rspace, rphysmap) = send_aspace(MapFlags::READ | MapFlags::USER, b"");
        aspaces
            .write()
            .register(SecTaskId(3), rspace, rphysmap)
            .expect("recipient registers");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let fs: &'static RecordingFs = Box::leak(Box::new(RecordingFs::new()));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_filesystem(fs);

        let fd = u32::try_from(
            h.fs_open(&ctx, 0x1000, "/f".len(), OpenFlags::READ)
                .expect("open read-only"),
        )
        .unwrap();
        let handle = h.fd_grant(&ctx, fd, 3).expect("grant mints a handle");

        // The grantor itself cannot redeem the handle it minted for the
        // recipient — a foreign handle answers exactly like one that never
        // existed.
        assert_eq!(h.fd_redeem(&ctx, handle), Err(Errno::NotFound));

        // The recipient redeems once: the installed descriptor is a
        // read-only delegated backing carrying the grantor's identity.
        let recipient_caps = TaskCapabilities::derive(
            SecTaskId(3),
            UserId(2000),
            caps_with(&[]),
            caps_with(&[]),
            sink,
        );
        let rctx = CallerContext {
            task_id: SecTaskId(3),
            caps: &recipient_caps,
        };
        let rfd = u32::try_from(h.fd_redeem(&rctx, handle).expect("redeem installs")).unwrap();
        let entry = aspaces
            .read()
            .open_file_entry(SecTaskId(3), rfd)
            .expect("descriptor recorded");
        assert_eq!(entry.flags, OpenFlags::READ);
        match &entry.backing {
            crate::aspace::OpenBacking::Delegated(file) => {
                assert_eq!(file.path, "/f");
                assert_eq!(file.uid, 1000, "the grantor's uid was captured");
            }
            other => panic!("expected a delegated backing, got {other:?}"),
        }

        // One-shot: a second redemption of the same handle is refused.
        assert_eq!(h.fd_redeem(&rctx, handle), Err(Errno::NotFound));
    }

    /// A redeemed delegation reads under the **grantor's** captured
    /// identity — the holder needs no filesystem capability of its own —
    /// and can never write through the delegated descriptor.
    #[test]
    fn delegated_read_runs_under_the_grantors_identity() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, b"/f");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        // The recipient's own memory must be writable for the read's
        // copy-out; its page also holds a path for the contrast open below.
        let (rspace, rphysmap) =
            send_aspace(MapFlags::READ | MapFlags::WRITE | MapFlags::USER, b"/f");
        aspaces
            .write()
            .register(SecTaskId(3), rspace, rphysmap)
            .expect("recipient registers");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let grantor_caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let gctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &grantor_caps,
        };
        // The recipient runs as a different user and holds **no**
        // capability at all.
        let recipient_caps = TaskCapabilities::derive(
            SecTaskId(3),
            UserId(2000),
            caps_with(&[]),
            caps_with(&[]),
            sink,
        );
        let rctx = CallerContext {
            task_id: SecTaskId(3),
            caps: &recipient_caps,
        };
        let mut mock = RecordingFs::new();
        mock.read_data = b"hello".to_vec();
        let fs: &'static RecordingFs = Box::leak(Box::new(mock));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_filesystem(fs);

        let fd = u32::try_from(
            h.fs_open(&gctx, 0x1000, "/f".len(), OpenFlags::READ)
                .expect("grantor opens"),
        )
        .unwrap();
        let handle = h.fd_grant(&gctx, fd, 3).expect("grant mints a handle");
        let rfd = u32::try_from(h.fd_redeem(&rctx, handle).expect("redeem installs")).unwrap();

        // The delegated read succeeds for the capability-less holder and
        // runs through the VFS under the grantor's uid, never the
        // holder's.
        let n = h.fs_read(&rctx, rfd, 0, 0x1000, 5).expect("delegated read");
        assert_eq!(n, 5);
        assert!(
            fs.calls()
                .iter()
                .any(|c| c.contains("read uid=1000 path=/f")),
            "the read was authorised under the grantor's captured identity: {:?}",
            fs.calls()
        );

        // The delegation is read-only: a write through it is refused by
        // the descriptor's own flags before the filesystem is touched
        // (the holder's absent `CAP_FS_ACCESS` never enters it — nothing
        // beyond the one delegated file was widened, which the
        // dispatcher's own capability gate enforces for every path-opening
        // syscall the holder might try).
        assert_eq!(
            h.fs_write(&rctx, rfd, 0, 0x1000, 2),
            Err(Errno::PermissionDenied)
        );

        // An exited recipient's pending delegations are reclaimed with the
        // rest of its records: a second grant minted to the recipient dies
        // with it and can never be redeemed by a later task.
        let second = h.fd_grant(&gctx, fd, 3).expect("second grant mints");
        aspaces.write().withdraw(SecTaskId(3));
        assert_eq!(
            aspaces.write().redeem_fd_delegation(SecTaskId(3), second),
            Err(Errno::NotFound),
            "withdraw reclaimed the pending delegation"
        );
    }

    /// `call_peer_seat` answers only while the ticket is in service, only
    /// for the endpoint's owning server, and reports the *live* lease of
    /// the peer: `SeatNotOwner` before an acquire, the minted generation
    /// while held, and the distinct `SeatRevoked` after an eviction
    /// (`plans/DISPLAY.md` D7a).
    #[test]
    fn call_peer_seat_reports_the_live_lease_of_the_in_service_peer() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;

        let queue: &'static crate::console::ConsoleInputQueue =
            Box::leak(Box::new(crate::console::ConsoleInputQueue::new()));
        let seat: &'static SeatRegistry = Box::leak(Box::new(SeatRegistry::new(queue)));

        let id = 0xCA11_5EA7;
        let server_caps = make_caps_record(0x5708, &[], sink);
        let ep = Arc::new(
            CallEndpoint::create(
                EndpointId(id),
                &server_caps,
                CapabilitySet::empty(),
                CapabilitySet::empty(),
                CallEndpointLimits {
                    max_request: 64,
                    max_reply: 64,
                    capacity: 4,
                },
                sink,
            )
            .expect("unrestricted endpoint"),
        );
        crate::callreg::register(ep.clone(), sink).expect("registered");

        // The client (task 7) posts a present request.
        let client_caps = make_caps_record(7, &[], sink);
        let ticket = ep.post(&client_caps, 7, b"present", sink).expect("posted");

        let ctx = CallerContext {
            task_id: SecTaskId(0x5708),
            caps: &server_caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_seat_registry(seat);

        // Not yet in service: the peer is not readable (fail closed).
        assert_eq!(
            h.call_peer_seat(&ctx, id, ticket.0, SEAT_PRIMARY),
            Err(Errno::NotFound)
        );
        // Move the call into service.
        let RecvCall::Received(call) = ep.recv_call(usize::MAX) else {
            panic!("posted call is receivable");
        };
        assert_eq!(call.ticket, ticket);

        // A foreign reader (not the endpoint's owner) is denied before any
        // seat state is read.
        let foreign_caps = make_caps_record(8, &[], sink);
        let foreign_ctx = CallerContext {
            task_id: SecTaskId(8),
            caps: &foreign_caps,
        };
        assert_eq!(
            h.call_peer_seat(&foreign_ctx, id, ticket.0, SEAT_PRIMARY),
            Err(Errno::PermissionDenied)
        );

        // The peer holds no lease: the typed SeatNotOwner refusal.
        assert_eq!(
            h.call_peer_seat(&ctx, id, ticket.0, SEAT_PRIMARY),
            Err(Errno::SeatNotOwner)
        );
        // The peer acquires the seat: the answer is the live generation.
        let lease = seat
            .acquire(SEAT_PRIMARY, SeatOwner(7))
            .expect("seat acquired");
        assert_eq!(
            h.call_peer_seat(&ctx, id, ticket.0, SEAT_PRIMARY),
            Ok(lease.generation)
        );
        // An unknown seat fails closed regardless of the lease.
        assert_eq!(
            h.call_peer_seat(&ctx, id, ticket.0, 999),
            Err(Errno::NotFound)
        );
        // After an administrative eviction the answer is the distinct
        // revoked refusal — the service refuses the present and the client
        // learns it lost the seat.
        let evicted = seat.revoke(SEAT_PRIMARY).expect("lease revoked");
        assert_eq!(evicted, SeatOwner(7));
        assert_eq!(
            h.call_peer_seat(&ctx, id, ticket.0, SEAT_PRIMARY),
            Err(Errno::SeatRevoked)
        );
        crate::callreg::unregister(EndpointId(id));
    }

    /// Adding a `SeatInput` wait-set member is owner-checked against the
    /// seat's live lease, and every refusal is the same oracle-free
    /// `NotFound` the other member kinds use (`plans/DISPLAY.md` D7a).
    #[test]
    fn waitset_seat_member_requires_the_live_lease() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let queue: &'static crate::console::ConsoleInputQueue =
            Box::leak(Box::new(crate::console::ConsoleInputQueue::new()));
        let seat: &'static SeatRegistry = Box::leak(Box::new(SeatRegistry::new(queue)));
        // Task ids unique to this test: the wait-set registry is process-
        // global, and another test asserts the exact count of sets it
        // releases for its own task id.
        let caps = make_caps_record(0x5709, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(0x5709),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_seat_registry(seat);

        let ws = h.waitset_create(&ctx).expect("wait-set minted");
        let add = WaitSetOp::Add.as_u32();
        let kind = WaitSourceKind::SeatInput.as_u32();
        // An unowned seat: the caller holds no lease, so the member is
        // refused without confirming the seat exists.
        assert_eq!(
            h.waitset_ctl(&ctx, ws, add, kind, SEAT_PRIMARY, 0xA),
            Err(Errno::NotFound)
        );
        // An unknown seat: the same refusal shape.
        assert_eq!(
            h.waitset_ctl(&ctx, ws, add, kind, 999, 0xA),
            Err(Errno::NotFound)
        );
        // The live owner may observe its seat.
        seat.acquire(SEAT_PRIMARY, SeatOwner(0x5709))
            .expect("seat acquired");
        assert_eq!(h.waitset_ctl(&ctx, ws, add, kind, SEAT_PRIMARY, 0xA), Ok(0));
        // A different task cannot observe someone else's seat, even knowing
        // its id — the same oracle-free refusal.
        let other_caps = make_caps_record(0x570A, &[], sink);
        let other_ctx = CallerContext {
            task_id: SecTaskId(0x570A),
            caps: &other_caps,
        };
        let other_set = h.waitset_create(&other_ctx).expect("wait-set minted");
        assert_eq!(
            h.waitset_ctl(&other_ctx, other_set, add, kind, SEAT_PRIMARY, 0xB),
            Err(Errno::NotFound)
        );
        // Cleanup: the wait-set registry is process-global, so this test
        // releases exactly the sets it minted, and the seat lease with them.
        assert_eq!(crate::waitset::release_owned_by(0x5709), 1);
        assert_eq!(crate::waitset::release_owned_by(0x570A), 1);
        seat.release(SEAT_PRIMARY, SeatOwner(0x5709))
            .expect("seat released");
    }

    /// `shm_create` on a build with no shared-memory facility wired fails
    /// closed with `NotImplemented`, never fabricating a region.
    #[test]
    fn shm_create_without_facility_is_not_implemented() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(9, &[CapabilityId::SHM], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(9),
            caps: &caps,
        };
        // No `with_shared_mem_facility`: the handler holds the fail-closed
        // `NULL_SHARED_MEM_FACILITY`.
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        assert_eq!(h.shm_create(&ctx, 4096, 0x2000), Err(Errno::NotImplemented));
        // A zero-length region is rejected before the facility is consulted.
        assert_eq!(h.shm_create(&ctx, 0, 0x2000), Err(Errno::LengthOutOfRange));
    }

    /// Wire constants for the wait-set control arguments, named so the tests
    /// read as the syscall's caller would write them.
    const WS_OP_ADD: u32 = rustos_abi::WaitSetOp::Add as u32;
    const WS_OP_DEL: u32 = rustos_abi::WaitSetOp::Del as u32;
    const WS_KIND_ENDPOINT: u32 = rustos_abi::WaitSourceKind::Endpoint as u32;
    const WS_KIND_IRQ: u32 = rustos_abi::WaitSourceKind::Irq as u32;
    const WS_KIND_CHILD: u32 = rustos_abi::WaitSourceKind::Child as u32;
    const WS_KIND_PORT: u32 = rustos_abi::WaitSourceKind::Port as u32;
    const WS_KIND_STREAM: u32 = rustos_abi::WaitSourceKind::Stream as u32;

    /// A [`ProcessWait`] test double over the real [`ProcessTable`]
    /// bookkeeping, so the wait-set `Child` tests exercise the same matcher
    /// the production producer uses.
    struct TableWait(rustos_sync::SpinLock<crate::procwait::ProcessTable>);

    impl TableWait {
        fn leaked() -> &'static Self {
            Box::leak(Box::new(Self(rustos_sync::SpinLock::new(
                crate::procwait::ProcessTable::new(),
            ))))
        }
    }

    impl ProcessWait for TableWait {
        fn wait(
            &self,
            _parent: SecTaskId,
            _pid: i32,
            _flags: WaitFlags,
        ) -> Result<crate::procwait::WaitedChild, Errno> {
            Err(Errno::NotImplemented)
        }

        fn poll(
            &self,
            parent: SecTaskId,
            pid: i32,
            flags: WaitFlags,
        ) -> Result<crate::procwait::WaitedChild, Errno> {
            match self.0.lock().reap(parent, pid, flags.is_stopped()) {
                crate::procwait::Reap::Ready(child) => Ok(child),
                crate::procwait::Reap::Blocked => Err(Errno::WouldBlock),
                crate::procwait::Reap::NoChild => Err(Errno::NotFound),
            }
        }

        fn register_child(&self, parent: SecTaskId, child: SecTaskId) {
            self.0.lock().register(parent, child);
        }

        fn record_exit(&self, task: SecTaskId, code: i32) {
            self.0.lock().record_exit(task, code);
        }

        fn child_state(&self, parent: SecTaskId, pid: i32) -> ChildPeek {
            self.0.lock().peek(parent, pid)
        }
    }

    /// `waitset_create` mints a handle, and `waitset_ctl(Add)` owner-checks the
    /// named resource against the caller before recording it: a bound IRQ line
    /// is accepted, a forged IRQ handle and an unknown endpoint are refused, a
    /// duplicate `(kind,id)` is refused, and `Del` round-trips. A forged set
    /// handle and an unknown op/kind all fail closed.
    #[test]
    fn waitset_create_and_ctl_owner_check_resources() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(8, &[CapabilityId::IRQ_BIND], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(8),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        let set = h.waitset_create(&ctx).expect("create mints a handle");
        assert!(set != 0, "handle is non-zero");

        // A line the caller bound is an acceptable IRQ member.
        let line = h.irq_bind(&ctx, 5).expect("bind");
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_IRQ, line, 0xAA),
            Ok(0)
        );
        // A forged IRQ handle the caller never bound is refused.
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_IRQ, 0xDEAD_BEEF, 0xBB),
            Err(Errno::NotFound)
        );
        // An unknown endpoint id is refused (the caller serves none).
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_ENDPOINT, 0x1234, 0xCC),
            Err(Errno::NotFound)
        );
        // A duplicate `(kind,id)` is refused even with a different token.
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_IRQ, line, 0x99),
            Err(Errno::AlreadyExists)
        );
        // `Del` removes the member; a second `Del` fails closed.
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_DEL, WS_KIND_IRQ, line, 0),
            Ok(0)
        );
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_DEL, WS_KIND_IRQ, line, 0),
            Err(Errno::NotFound)
        );
        // A handle that is not the caller's own wait-set fails closed.
        assert_eq!(
            h.waitset_ctl(&ctx, set + 999, WS_OP_ADD, WS_KIND_IRQ, line, 0),
            Err(Errno::NotFound)
        );
        // Unknown op / kind are rejected before any state is touched.
        assert_eq!(
            h.waitset_ctl(&ctx, set, 7, WS_KIND_IRQ, line, 0),
            Err(Errno::OutOfRange)
        );
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_ADD, 7, line, 0),
            Err(Errno::OutOfRange)
        );

        // Cleanup so the global wait-set registry does not leak across tests.
        assert_eq!(crate::waitset::release_owned_by(8), 1);
    }

    /// `waitset_wait` with no member ready and a zero timeout returns
    /// `TimedOut` without writing `token_out` (so it needs no mapped page).
    #[test]
    fn waitset_wait_times_out_when_no_member_ready() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(0x5701, &[CapabilityId::IRQ_BIND], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(0x5701),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        let set = h.waitset_create(&ctx).expect("create");
        let line = h.irq_bind(&ctx, 5).expect("bind");
        h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_IRQ, line, 0xAA)
            .expect("add irq member");
        // The line has not fired: a zero-timeout wait expires without writing.
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Err(Errno::TimedOut));
        assert_eq!(crate::waitset::release_owned_by(0x5701), 1);
    }

    /// A fired IRQ member makes `waitset_wait` report that member's token and
    /// consume the edge: the token is written to `token_out`, and a second
    /// wait times out (the fire was consumed, exactly like `irq_wait`).
    #[test]
    fn waitset_wait_reports_a_fired_irq_member_and_consumes_the_edge() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = call_aspace(b"");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(7), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let permissive = PermissiveController;
        let caps = make_caps_record(7, &[CapabilityId::IRQ_BIND], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(7),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        let set = h.waitset_create(&ctx).expect("create");
        let line = h.irq_bind(&ctx, 5).expect("bind");
        h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_IRQ, line, 0x1234)
            .expect("add irq member");

        // Fire the line externally (the arch trap path would do this); the
        // ready flag is then set.
        irq.fire(5, &permissive).expect("fire");
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Ok(0));
        // The ready member's token was written to `token_out` (page 2).
        let token_bytes = read_reply_page(
            aspaces.read().resolve(SecTaskId(7)).expect("registered").1,
            8,
        );
        assert_eq!(
            u64::from_le_bytes(token_bytes.try_into().expect("8 bytes")),
            0x1234
        );
        // The edge was consumed: a second wait with no new fire times out.
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Err(Errno::TimedOut));
        assert_eq!(crate::waitset::release_owned_by(7), 1);
    }

    /// A pending request on a member endpoint makes `waitset_wait` report that
    /// member's token (a non-consuming peek), and `call_recv` is what drains
    /// it: after draining, a second wait times out.
    #[test]
    fn waitset_wait_reports_a_pending_endpoint_member_drained_by_recv() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = call_aspace(b"");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(0x5702), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(0x5702, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(0x5702),
            caps: &caps,
        };

        // An unrestricted endpoint owned by the caller (task 7), with a posted
        // request waiting to be received (so `has_pending()` is true).
        let id = 0xCA11_5001;
        let creator = make_caps_record(0x5702, &[], sink);
        let ep = Arc::new(
            CallEndpoint::create(
                EndpointId(id),
                &creator,
                CapabilitySet::empty(),
                CapabilitySet::empty(),
                CallEndpointLimits {
                    max_request: 64,
                    max_reply: 64,
                    capacity: 4,
                },
                sink,
            )
            .expect("endpoint"),
        );
        crate::callreg::register(ep.clone(), sink).expect("registered");
        let poster = make_caps_record(99, &[], sink);
        ep.post(&poster, 99, b"x", sink).expect("post a request");

        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        let set = h.waitset_create(&ctx).expect("create");
        h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_ENDPOINT, id, 0x77)
            .expect("add endpoint member");

        // The pending request makes the endpoint member ready; its token is
        // reported.
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Ok(0));
        let token_bytes = read_reply_page(
            aspaces
                .read()
                .resolve(SecTaskId(0x5702))
                .expect("registered")
                .1,
            8,
        );
        assert_eq!(
            u64::from_le_bytes(token_bytes.try_into().expect("8 bytes")),
            0x77
        );
        // The wait did not consume the request (it only peeked); draining it
        // with `recv_call` is what clears readiness, after which a second wait
        // times out.
        assert!(matches!(ep.recv_call(usize::MAX), RecvCall::Received(_)));
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Err(Errno::TimedOut));

        crate::callreg::unregister(EndpointId(id));
        assert_eq!(crate::waitset::release_owned_by(0x5702), 1);
    }

    /// `port_bind` binds a port owned by the kernel-trusted caller, refuses
    /// a clashing id (`AlreadyExists`, never a silent re-point), and
    /// re-applies the fail-closed bounds: a zero capacity and a payload cap
    /// beyond the ABI ceiling are both `LengthOutOfRange`.
    #[test]
    fn port_bind_binds_an_owned_port_and_refuses_clash_and_bad_bounds() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(0x5704, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(0x5704),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        let id = 0x5EAD_0001u64;
        assert_eq!(h.port_bind(&ctx, id, 64, 4), Ok(0));
        // The port exists and is owned by the caller (the receive gate's
        // and the wait-set's owner fact).
        assert_eq!(
            ipc.read()
                .lookup(EndpointId(id))
                .map(rustos_kernel_ipc::Port::owner),
            Some(0x5704)
        );
        // A live id is never silently re-pointed — not even by its owner.
        assert_eq!(h.port_bind(&ctx, id, 64, 4), Err(Errno::AlreadyExists));
        // Fail-closed bounds: zero capacity, oversize payload cap, and a
        // payload cap that does not fit the ABI register width.
        assert_eq!(
            h.port_bind(&ctx, 0x5EAD_0002, 64, 0),
            Err(Errno::LengthOutOfRange)
        );
        assert_eq!(
            h.port_bind(
                &ctx,
                0x5EAD_0003,
                rustos_abi::ipc::IPC_MESSAGE_MAX_PAYLOAD_LEN as usize + 1,
                4
            ),
            Err(Errno::LengthOutOfRange)
        );
        ipc.write().teardown_owned_by(0x5704, sink);
    }

    /// Binding a **reserved** well-known endpoint id as a port requires
    /// `CAP_IPC_BIND_PRIVILEGED`, exactly as `call_create` does: an
    /// unprivileged squatter is refused and the id stays unbound; a
    /// privileged binder succeeds.
    #[test]
    fn port_bind_reserved_id_requires_privileged_bind() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let reserved = rustos_abi::sysinfo::SYSINFO_ENDPOINT;

        let squatter_caps = make_caps_record(0x5705, &[], sink);
        let squatter = CallerContext {
            task_id: SecTaskId(0x5705),
            caps: &squatter_caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        assert_eq!(
            h.port_bind(&squatter, reserved, 64, 4),
            Err(Errno::PermissionDenied)
        );
        assert!(ipc.read().lookup(EndpointId(reserved)).is_none());

        let privileged_caps = make_caps_record(0x5706, &[CapabilityId::IPC_BIND_PRIVILEGED], sink);
        let privileged = CallerContext {
            task_id: SecTaskId(0x5706),
            caps: &privileged_caps,
        };
        assert_eq!(h.port_bind(&privileged, reserved, 64, 4), Ok(0));
        ipc.write().teardown_owned_by(0x5706, sink);
    }

    /// A delivered message on a member port makes `waitset_wait` report
    /// that member's token (a non-consuming peek), `ipc_recv` is what
    /// drains it, and a foreign port can never be added as a member: the
    /// full park-free slice of the app event-channel loop
    /// (`plans/APPWIN.md` AW3).
    #[test]
    fn waitset_wait_reports_a_pending_port_member_drained_by_ipc_recv() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = call_aspace(b"");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(0x5707), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(0x5707, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(0x5707),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        // The caller's own event port plus a foreign task's port.
        let id = 0x5EAD_0011u64;
        assert_eq!(h.port_bind(&ctx, id, 64, 4), Ok(0));
        register_port_for(&ipc, 0x5EAD_0012, 0xF0F0, sink);

        let set = h.waitset_create(&ctx).expect("create");
        // Observing another task's mailbox is refused with the same
        // `NotFound` an unknown id produces (no existence oracle).
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_PORT, 0x5EAD_0012, 0x31),
            Err(Errno::NotFound)
        );
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_PORT, 0xDEAD_0000, 0x32),
            Err(Errno::NotFound)
        );
        h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_PORT, id, 0x33)
            .expect("add own port member");

        // Nothing delivered yet: a zero-timeout wait expires.
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Err(Errno::TimedOut));

        // A delivered message makes the member ready and reports its token.
        enqueue(&ipc, id, &[0xEE; 4], sink);
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Ok(0));
        let token_bytes = read_reply_page(
            aspaces
                .read()
                .resolve(SecTaskId(0x5707))
                .expect("registered")
                .1,
            8,
        );
        assert_eq!(
            u64::from_le_bytes(token_bytes.try_into().expect("8 bytes")),
            0x33
        );

        // The wait only peeked; `ipc_recv` drains, after which a second
        // wait times out again.
        assert_eq!(h.ipc_recv(&ctx, id, 0x1000, 64, 0x1800), Ok(4));
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Err(Errno::TimedOut));

        ipc.write().teardown_owned_by(0x5707, sink);
        ipc.write().teardown_owned_by(0xF0F0, sink);
        assert_eq!(crate::waitset::release_owned_by(0x5707), 1);
    }

    /// Adding a `Stream` wait-set member is owner- and descriptor-checked
    /// against the caller's own open table: only the caller's own pipe
    /// read end qualifies, and every refusal is the same oracle-free
    /// `NotFound` the other member kinds use (`plans/APPWIN.md` AW4).
    #[test]
    fn waitset_stream_member_requires_the_callers_pipe_read_end() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        // Task ids unique to this test: the wait-set registry is process-
        // global and another test asserts the exact count of sets it
        // releases for its own task id.
        let caps = make_caps_record(0x570B, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(0x570B),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        // A foreign task's pipe first, then the caller's own path-backed
        // descriptor and pipe. Descriptor numbers are per-task, so the
        // foreign read end's *number* resolves in the caller's own table
        // (here to the path-backed entry) — a member id can never reach
        // another task's resource, only mis-name one of the caller's own.
        let (foreign_read_fd, _foreign_write_fd) = aspaces
            .write()
            .open_pipe(SecTaskId(0x570C))
            .expect("foreign pipe minted");
        let file_fd = aspaces
            .write()
            .open_file(
                SecTaskId(0x570B),
                alloc::string::String::from("/Storage/x"),
                OpenFlags::READ,
            )
            .expect("file opened");
        assert_eq!(
            foreign_read_fd, file_fd,
            "the foreign number lands on the caller's path-backed entry"
        );
        let (read_fd, write_fd) = aspaces
            .write()
            .open_pipe(SecTaskId(0x570B))
            .expect("pipe minted");

        let set = h.waitset_create(&ctx).expect("create");
        // A write end, a path-backed descriptor (also the foreign read
        // end's number), an unopened number, and an id outside the
        // descriptor width are all refused with the same oracle-free
        // `NotFound`.
        for id in [
            u64::from(write_fd),
            u64::from(file_fd),
            999,
            u64::from(u32::MAX) + 1,
        ] {
            assert_eq!(
                h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_STREAM, id, 0x41),
                Err(Errno::NotFound)
            );
        }
        h.waitset_ctl(
            &ctx,
            set,
            WS_OP_ADD,
            WS_KIND_STREAM,
            u64::from(read_fd),
            0x42,
        )
        .expect("add own pipe read end");

        // Cleanup: this test's own sets and tables only.
        assert_eq!(crate::waitset::release_owned_by(0x570B), 1);
        assert!(aspaces.write().withdraw(SecTaskId(0x570C)));
    }

    /// A `Stream` member reports readiness as a non-consuming peek when
    /// bytes arrive, keeps reporting until the owner's read drains them,
    /// and reports the end-of-stream a closed writer leaves behind — the
    /// terminal's shell-output wake slice (`plans/APPWIN.md` AW4).
    #[test]
    fn waitset_stream_member_reports_bytes_and_eof_without_consuming() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = call_aspace(b"");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(0x570D), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(0x570D, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(0x570D),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        let (read_fd, write_fd) = aspaces
            .write()
            .open_pipe(SecTaskId(0x570D))
            .expect("pipe minted");
        let set = h.waitset_create(&ctx).expect("create");
        h.waitset_ctl(
            &ctx,
            set,
            WS_OP_ADD,
            WS_KIND_STREAM,
            u64::from(read_fd),
            0x42,
        )
        .expect("add own pipe read end");

        // Empty with a live writer: a zero-timeout wait expires.
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Err(Errno::TimedOut));

        // Buffered bytes make the member ready and report its token; the
        // wait only peeked, so it stays ready until the owner's read
        // drains it.
        let write_end = aspaces
            .read()
            .open_file_entry(SecTaskId(0x570D), write_fd)
            .and_then(|entry| entry.pipe().cloned())
            .expect("write end resolves");
        assert_eq!(
            write_end.try_write(b"out"),
            crate::pipe::WriteStep::Wrote(3)
        );
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Ok(0));
        let token_bytes = read_reply_page(
            aspaces
                .read()
                .resolve(SecTaskId(0x570D))
                .expect("registered")
                .1,
            8,
        );
        assert_eq!(
            u64::from_le_bytes(token_bytes.try_into().expect("8 bytes")),
            0x42
        );
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Ok(0));

        // The owner's read drains the bytes; the member goes quiet again.
        let read_end = aspaces
            .read()
            .open_file_entry(SecTaskId(0x570D), read_fd)
            .and_then(|entry| entry.pipe().cloned())
            .expect("read end resolves");
        let mut out = [0u8; 8];
        assert_eq!(read_end.try_read(&mut out), crate::pipe::ReadStep::Read(3));
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Err(Errno::TimedOut));

        // Closing every write end leaves the member ready for its EOF
        // read (the shell-exited wake), never parked forever.
        drop(write_end);
        assert!(aspaces.write().close_file(SecTaskId(0x570D), write_fd));
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Ok(0));
        assert_eq!(read_end.try_read(&mut out), crate::pipe::ReadStep::Eof);

        // Cleanup: this test's own sets and tables only.
        assert_eq!(crate::waitset::release_owned_by(0x570D), 1);
        assert!(aspaces.write().withdraw(SecTaskId(0x570D)));
    }

    /// Task-exit reclamation tears down every port the dead task bound:
    /// the id resolves to nothing afterwards (so a later task can never
    /// squat on a dead task's mailbox) and a racing sender observes the
    /// typed `NotFound`.
    #[test]
    fn reclaim_task_resources_tears_down_owned_ports() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(0x5708, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(0x5708),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        let id = 0x5EAD_0021u64;
        assert_eq!(h.port_bind(&ctx, id, 64, 4), Ok(0));
        // Another task's port survives the reclaim untouched.
        register_port_for(&ipc, 0x5EAD_0022, 0xF0F1, sink);

        h.reclaim_task_resources(SecTaskId(0x5708));
        assert!(ipc.read().lookup(EndpointId(id)).is_none());
        assert!(ipc.read().lookup(EndpointId(0x5EAD_0022)).is_some());

        // A racing sender fails typed, never delivers into a dead mailbox.
        assert_eq!(h.ipc_send(&ctx, id, 0x1000, 4), Err(Errno::NotFound));

        ipc.write().teardown_owned_by(0xF0F1, sink);
    }

    /// `waitset_ctl(Add)` owner-checks a `Child` member: before a producer
    /// is installed a specific pid fails closed; with one installed, the
    /// caller's own child is accepted, a pid that is not the caller's child
    /// (or is unrepresentable) is refused, and the ANY sentinel is admitted
    /// so a supervisor can register before its first spawn.
    #[test]
    fn waitset_ctl_owner_checks_child_members() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(0x5703, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(0x5703),
            caps: &caps,
        };

        // No producer installed (`NULL_PROCESS_WAIT`): a specific pid names
        // no child — fail closed, never fabricate a relationship.
        let bare = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        let set = bare.waitset_create(&ctx).expect("create");
        assert_eq!(
            bare.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_CHILD, 21, 0x11),
            Err(Errno::NotFound)
        );

        // With the producer installed and child 21 registered to the caller.
        let pw = TableWait::leaked();
        pw.register_child(SecTaskId(0x5703), SecTaskId(21));
        pw.register_child(SecTaskId(0x9999), SecTaskId(22));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_process_wait(pw);
        // The caller's own child is an acceptable member.
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_CHILD, 21, 0x11),
            Ok(0)
        );
        // Another parent's child is refused without confirming it exists.
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_CHILD, 22, 0x22),
            Err(Errno::NotFound)
        );
        // An id no pid can represent names no child.
        assert_eq!(
            h.waitset_ctl(&ctx, set, WS_OP_ADD, WS_KIND_CHILD, u64::MAX - 1, 0x33),
            Err(Errno::NotFound)
        );
        // The ANY sentinel is admitted — it can only ever match the
        // caller's own children, spawned before or after the add.
        assert_eq!(
            h.waitset_ctl(
                &ctx,
                set,
                WS_OP_ADD,
                WS_KIND_CHILD,
                rustos_abi::WAITSET_CHILD_ANY,
                0x44
            ),
            Ok(0)
        );

        assert_eq!(crate::waitset::release_owned_by(0x5703), 1);
    }

    /// A reapable child makes `waitset_wait` report the `Child` member's
    /// token as a non-consuming peek: the zombie stays reapable (a second
    /// wait still reports it) until the non-blocking reap drains it, after
    /// which the wait times out again.
    #[test]
    fn waitset_wait_reports_a_reapable_child_without_consuming() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = call_aspace(b"");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(0x5704), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(0x5704, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(0x5704),
            caps: &caps,
        };
        let pw = TableWait::leaked();
        pw.register_child(SecTaskId(0x5704), SecTaskId(21));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_process_wait(pw);
        let set = h.waitset_create(&ctx).expect("create");
        h.waitset_ctl(
            &ctx,
            set,
            WS_OP_ADD,
            WS_KIND_CHILD,
            rustos_abi::WAITSET_CHILD_ANY,
            0x55,
        )
        .expect("add child member");

        // The child is still running: nothing is ready.
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Err(Errno::TimedOut));

        // The child exits: the member is ready and its token is written.
        pw.record_exit(SecTaskId(21), 3);
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Ok(0));
        let token_bytes = read_reply_page(
            aspaces
                .read()
                .resolve(SecTaskId(0x5704))
                .expect("registered")
                .1,
            8,
        );
        assert_eq!(
            u64::from_le_bytes(token_bytes.try_into().expect("8 bytes")),
            0x55
        );
        // The wait did not reap (it only peeked): the member is still ready.
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Ok(0));
        // The non-blocking reap is what drains readiness — the exact reap
        // the `wait` syscall's NONBLOCK form performs after the wake.
        assert_eq!(
            pw.poll(
                SecTaskId(0x5704),
                rustos_abi::WAIT_PID_ANY,
                WaitFlags::NONBLOCK
            ),
            Ok(crate::procwait::WaitedChild {
                pid: 21,
                status: rustos_abi::WaitStatus::Exited(3),
            })
        );
        assert_eq!(h.waitset_wait(&ctx, set, 0, 0x2000), Err(Errno::TimedOut));

        assert_eq!(crate::waitset::release_owned_by(0x5704), 1);
    }

    /// `call_recv` / `call_reply` against an unbound id fail closed with
    /// `NotFound` before touching any buffer.
    #[test]
    fn call_recv_and_reply_on_unknown_endpoint_are_not_found() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        assert_eq!(
            h.call_recv(
                &ctx,
                0xDEAD_3001,
                0x1000,
                64,
                0x2000,
                CallRecvFlags::empty()
            ),
            Err(Errno::NotFound)
        );
        assert_eq!(
            h.call_reply(&ctx, 0xDEAD_3001, 1, 0x1000, 4),
            Err(Errno::NotFound)
        );
    }

    /// A server lacking the endpoint's required receive capability is denied
    /// at `call_recv` before any state is touched.
    #[test]
    fn call_recv_without_required_recv_cap_is_permission_denied() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;

        // The endpoint requires CAP_AUDIT_READ to serve; its creator holds it.
        let id = 0xCA11_3002;
        let creator = make_caps_record(1, &[CapabilityId::AUDIT_READ], sink);
        let mut recv_caps = CapabilitySet::empty();
        recv_caps.insert(CapabilityId::AUDIT_READ);
        let ep = Arc::new(
            CallEndpoint::create(
                EndpointId(id),
                &creator,
                CapabilitySet::empty(),
                recv_caps,
                CallEndpointLimits {
                    max_request: 64,
                    max_reply: 64,
                    capacity: 4,
                },
                sink,
            )
            .expect("restricted-recv endpoint"),
        );
        crate::callreg::register(ep, sink).expect("registered");

        // The caller (task 2) does not hold CAP_AUDIT_READ.
        let caps = make_caps_record(2, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        assert_eq!(
            h.call_recv(&ctx, id, 0x1000, 64, 0x2000, CallRecvFlags::empty()),
            Err(Errno::PermissionDenied)
        );
        crate::callreg::unregister(EndpointId(id));
    }

    /// End-to-end server side: a posted request is delivered by `call_recv`
    /// (request bytes + ticket), and `call_reply` completes it for the
    /// client. The serving task is the endpoint owner.
    #[test]
    fn call_recv_and_reply_round_trip_the_server_side() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = server_aspace(b"pong");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        // The server task owns the endpoint, so the aspace and the owner id
        // are the same task. The id is unique to this test: the endpoint
        // registry is process-global, and an `exit` test for a shared id
        // running in parallel would tear this endpoint down mid-receive.
        aspaces
            .write()
            .register(SecTaskId(0x5705), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;

        // Build the endpoint owned by the server task.
        let id = 0xCA11_3003;
        let server_caps = make_caps_record(0x5705, &[], sink);
        let ep = Arc::new(
            CallEndpoint::create(
                EndpointId(id),
                &server_caps,
                CapabilitySet::empty(),
                CapabilitySet::empty(),
                CallEndpointLimits {
                    max_request: 64,
                    max_reply: 64,
                    capacity: 4,
                },
                sink,
            )
            .expect("unrestricted endpoint"),
        );
        crate::callreg::register(ep.clone(), sink).expect("registered");

        // A client (task 7) posts a request, awaiting its reply.
        let client_caps = make_caps_record(7, &[], sink);
        let ticket = ep.post(&client_caps, 7, b"ping", sink).expect("posted");

        let ctx = CallerContext {
            task_id: SecTaskId(0x5705),
            caps: &server_caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        // `call_recv` delivers the request to page 1 and the ticket to page 2.
        let got = h
            .call_recv(&ctx, id, 0x1000, 64, 0x2000, CallRecvFlags::empty())
            .expect("received");
        assert_eq!(got, 4);
        let guard = aspaces.read();
        let (_space, physmap) = guard.resolve(SecTaskId(0x5705)).expect("aspace present");
        assert_eq!(read_server_page(physmap, 1, 4), b"ping");
        let ticket_bytes = read_server_page(physmap, 2, 8);
        let recv_ticket = u64::from_le_bytes(ticket_bytes.try_into().expect("8 bytes"));
        assert_eq!(recv_ticket, ticket.0);
        drop(guard);

        // `call_reply` sends page 3's payload back and completes the ticket.
        assert_eq!(h.call_reply(&ctx, id, recv_ticket, 0x3000, 4), Ok(0));
        // The client claims its reply exactly once.
        assert_eq!(
            ep.take_reply(7, CallTicket(recv_ticket)),
            ReplyOutcome::Ready(b"pong".to_vec())
        );
        crate::callreg::unregister(EndpointId(id));
    }

    /// A non-blocking `call_recv` answers an empty queue with `WouldBlock`
    /// instead of parking — the wait-set event-loop mode — and still drains
    /// a queued request normally.
    #[test]
    fn nonblocking_call_recv_answers_an_empty_queue_with_would_block() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = server_aspace(b"idle");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        // Unique server task + endpoint id (the registry is process-global).
        aspaces
            .write()
            .register(SecTaskId(0x5707), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;

        let id = 0xCA11_5005;
        let server_caps = make_caps_record(0x5707, &[], sink);
        let ep = Arc::new(
            CallEndpoint::create(
                EndpointId(id),
                &server_caps,
                CapabilitySet::empty(),
                CapabilitySet::empty(),
                CallEndpointLimits {
                    max_request: 64,
                    max_reply: 64,
                    capacity: 4,
                },
                sink,
            )
            .expect("unrestricted endpoint"),
        );
        crate::callreg::register(ep.clone(), sink).expect("registered");

        let ctx = CallerContext {
            task_id: SecTaskId(0x5707),
            caps: &server_caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        // Nothing queued: the non-blocking receive answers instead of parking.
        assert_eq!(
            h.call_recv(&ctx, id, 0x1000, 64, 0x2000, CallRecvFlags::NON_BLOCKING),
            Err(Errno::WouldBlock)
        );

        // A queued request is still drained normally in the same mode.
        let client_caps = make_caps_record(7, &[], sink);
        let _ = ep.post(&client_caps, 7, b"ping", sink).expect("posted");
        let got = h
            .call_recv(&ctx, id, 0x1000, 64, 0x2000, CallRecvFlags::NON_BLOCKING)
            .expect("received");
        assert_eq!(got, 4);
        crate::callreg::unregister(EndpointId(id));
    }

    /// Task-exit reclamation cancels the calls the dead task *posted*: a
    /// queued request from a killed caller is never later handed to the
    /// server (the Pi 4 keyboard-wedge regression — a dead class driver's
    /// final URB submit was held by the HCD after a fault recovery and
    /// refused its replacement's every submit as `AlreadyExists`).
    #[test]
    fn reclaim_scrubs_a_dead_posters_queued_call() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;

        // Unique server task + endpoint id (the registry is process-global).
        let id = 0xCA11_6006;
        let server_caps = make_caps_record(0x5708, &[], sink);
        let ep = Arc::new(
            CallEndpoint::create(
                EndpointId(id),
                &server_caps,
                CapabilitySet::empty(),
                CapabilitySet::empty(),
                CallEndpointLimits {
                    max_request: 64,
                    max_reply: 64,
                    capacity: 4,
                },
                sink,
            )
            .expect("unrestricted endpoint"),
        );
        crate::callreg::register(ep.clone(), sink).expect("registered");

        // A client (task 9) posts and is then killed before the server
        // receives.
        let client_caps = make_caps_record(9, &[], sink);
        let _ = ep.post(&client_caps, 9, b"stale", sink).expect("posted");
        assert!(ep.has_pending());

        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        h.reclaim_task_resources(SecTaskId(9));

        // The dead poster's call is gone before any server sees it.
        assert!(!ep.has_pending());
        crate::callreg::unregister(EndpointId(id));
    }

    /// `call_peer_origin` hands the server the kernel-attested identity of
    /// the caller it is servicing, immune to the request payload, and fails
    /// closed for a foreign reader, a short buffer, or a ticket not in
    /// service.
    #[test]
    fn call_peer_origin_attests_the_caller_and_fails_closed() {
        use rustos_abi::{Origin, ProcId, TrustDomain, ORIGIN_WIRE_LEN};
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = server_aspace(b"unused");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        // The server task owns both the aspace and the endpoint. The id is
        // unique to this test: the endpoint registry is process-global, and
        // an `exit` test for a shared id running in parallel would tear this
        // endpoint down mid-receive.
        aspaces
            .write()
            .register(SecTaskId(0x5706), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;

        let id = 0xCA11_4004;
        let server_caps = make_caps_record(0x5706, &[], sink);
        let ep = Arc::new(
            CallEndpoint::create(
                EndpointId(id),
                &server_caps,
                CapabilitySet::empty(),
                CapabilitySet::empty(),
                CallEndpointLimits {
                    max_request: 64,
                    max_reply: 64,
                    capacity: 4,
                },
                sink,
            )
            .expect("unrestricted endpoint"),
        );
        crate::callreg::register(ep.clone(), sink).expect("registered");

        // A client (task 7) with a minted process instance and a real
        // capability posts a request.
        let client_caps = make_caps_record(7, &[CapabilityId::SYSINFO_GLOBAL], sink)
            .with_proc_id(ProcId::from_raw([0x71; 16]));
        let expected = client_caps.attest_origin();
        let ticket = ep.post(&client_caps, 7, b"who-am-i", sink).expect("posted");

        let ctx = CallerContext {
            task_id: SecTaskId(0x5706),
            caps: &server_caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        // Before the server receives the call, the ticket is not in service,
        // so the origin is not yet readable (fail closed). The buffer is
        // large enough for a whole origin so the in-service check is what
        // fires, not the size check.
        assert_eq!(
            h.call_peer_origin(&ctx, id, ticket.0, 0x1000, ORIGIN_WIRE_LEN),
            Err(Errno::NotFound)
        );

        // Receive the call, moving it into service.
        let got = h
            .call_recv(&ctx, id, 0x2000, 64, 0x3000, CallRecvFlags::empty())
            .expect("received");
        assert_eq!(got, 8);

        // A foreign reader (task 8, not the owner) is denied before any
        // state is touched.
        let foreign_caps = make_caps_record(8, &[], sink);
        let foreign_ctx = CallerContext {
            task_id: SecTaskId(8),
            caps: &foreign_caps,
        };
        assert_eq!(
            h.call_peer_origin(&foreign_ctx, id, ticket.0, 0x1000, 64),
            Err(Errno::PermissionDenied)
        );

        // A buffer too small for a whole origin fails closed.
        assert_eq!(
            h.call_peer_origin(&ctx, id, ticket.0, 0x1000, ORIGIN_WIRE_LEN - 1),
            Err(Errno::BufferTooSmall)
        );

        // An unknown ticket fails closed.
        assert_eq!(
            h.call_peer_origin(&ctx, id, 0xDEAD, 0x1000, ORIGIN_WIRE_LEN),
            Err(Errno::NotFound)
        );

        // The happy path writes the attested origin to page 1.
        let wrote = h
            .call_peer_origin(&ctx, id, ticket.0, 0x1000, ORIGIN_WIRE_LEN)
            .expect("origin written");
        assert_eq!(wrote, ORIGIN_WIRE_LEN as u64);

        let guard = aspaces.read();
        let (_space, physmap) = guard.resolve(SecTaskId(0x5706)).expect("aspace present");
        let bytes = read_server_page(physmap, 1, ORIGIN_WIRE_LEN);
        let decoded = Origin::from_bytes(&bytes).expect("valid origin");
        drop(guard);

        // It is exactly what the client's own record attests — proving the
        // server reads kernel-attested state, never the request payload.
        assert_eq!(decoded, expected);
        assert_eq!(decoded.trust_domain(), TrustDomain::User);
        assert_eq!(decoded.uid(), 1000);
        assert_eq!(decoded.pid(), 7);
        assert_eq!(decoded.proc_id(), ProcId::from_raw([0x71; 16]));
        assert!(decoded
            .capabilities()
            .holds_cap(CapabilityId::SYSINFO_GLOBAL));

        crate::callreg::unregister(EndpointId(id));
    }

    /// `self_origin` copies out the caller's *own* kernel-attested origin,
    /// built from its own task record (never a caller-supplied value), and
    /// fails closed on a buffer shorter than a whole origin.
    #[test]
    fn self_origin_attests_the_caller_and_fails_closed() {
        use rustos_abi::{Origin, ProcId, TrustDomain, ORIGIN_WIRE_LEN};
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = server_aspace(b"unused");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(9), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;

        // The caller (task 9) has a minted process instance and a real
        // capability, so its attested origin is non-trivial.
        let caps = make_caps_record(9, &[CapabilityId::SYSINFO_GLOBAL], sink)
            .with_proc_id(ProcId::from_raw([0x99; 16]));
        let expected = caps.attest_origin();
        let ctx = CallerContext {
            task_id: SecTaskId(9),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        // A buffer too small for a whole origin fails closed, before any copy.
        assert_eq!(
            h.self_origin(&ctx, 0x1000, ORIGIN_WIRE_LEN - 1),
            Err(Errno::BufferTooSmall)
        );

        // The happy path writes the caller's own attested origin to page 1.
        let wrote = h
            .self_origin(&ctx, 0x1000, ORIGIN_WIRE_LEN)
            .expect("origin written");
        assert_eq!(wrote, ORIGIN_WIRE_LEN as u64);

        let guard = aspaces.read();
        let (_space, physmap) = guard.resolve(SecTaskId(9)).expect("aspace present");
        let bytes = read_server_page(physmap, 1, ORIGIN_WIRE_LEN);
        let decoded = Origin::from_bytes(&bytes).expect("valid origin");
        drop(guard);

        // It is exactly what the caller's own record attests — proving the
        // kernel builds it from task state, never a caller claim.
        assert_eq!(decoded, expected);
        assert_eq!(decoded.trust_domain(), TrustDomain::User);
        assert_eq!(decoded.pid(), 9);
        assert_eq!(decoded.proc_id(), ProcId::from_raw([0x99; 16]));
        assert!(decoded
            .capabilities()
            .holds_cap(CapabilityId::SYSINFO_GLOBAL));
    }

    /// `wall_time_get` / `wall_time_set` round-trip the kernel wall clock
    /// through the real handlers and the address-space copy paths, and fail
    /// closed on a short buffer, a non-settable state, and a malformed
    /// instant (P-D).
    #[test]
    fn wall_time_get_and_set_round_trip_and_fail_closed() {
        use rustos_abi::{Time64, WallClockReading, WallTimeState};
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // Seed page 3 (`0x3000`) with the `Time64` the set path copies in.
        // Nanos are 0 so the few-ns monotonic elapsed a later read adds never
        // carries into the seconds, keeping the assertion deterministic.
        let wall = Time64::from_secs(1_700_000_000);
        let (space, physmap) = server_aspace(&wall.to_le_bytes());
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(9), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(9, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(9),
            caps: &caps,
        };
        // The boot path leaks the production clock; tests do the same so the
        // `'static` builder is satisfied and a set persists across reads.
        let clock: &'static crate::wallclock::KernelWallClock =
            Box::leak(Box::new(crate::wallclock::KernelWallClock::new()));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_wall_clock(clock);

        // A buffer too small for a whole reading fails closed.
        assert_eq!(
            h.wall_time_get(&ctx, 0x1000, WallClockReading::WIRE_LEN - 1),
            Err(Errno::BufferTooSmall)
        );

        // Before any set, get reports the Unset epoch reading.
        let wrote = h.wall_time_get(&ctx, 0x1000, 64).expect("reading written");
        assert_eq!(wrote, WallClockReading::WIRE_LEN as u64);
        {
            let guard = aspaces.read();
            let (_s, pm) = guard.resolve(SecTaskId(9)).expect("aspace present");
            let bytes = read_server_page(pm, 1, WallClockReading::WIRE_LEN);
            let r = WallClockReading::from_bytes(&bytes).expect("valid reading");
            assert_eq!(r.state(), WallTimeState::Unset);
            assert_eq!(r.time(), Time64::UNIX_EPOCH);
        }

        // Setting to `Unset` is rejected (fail closed).
        assert_eq!(
            h.wall_time_set(
                &ctx,
                0x3000,
                Time64::WIRE_LEN,
                u32::from(WallTimeState::Unset.as_u8())
            ),
            Err(Errno::OutOfRange)
        );
        // An undefined state discriminant is rejected.
        assert_eq!(
            h.wall_time_set(&ctx, 0x3000, Time64::WIRE_LEN, 9),
            Err(Errno::OutOfRange)
        );
        // A short instant buffer fails closed.
        assert_eq!(
            h.wall_time_set(
                &ctx,
                0x3000,
                Time64::WIRE_LEN - 1,
                u32::from(WallTimeState::Trusted.as_u8())
            ),
            Err(Errno::BufferTooSmall)
        );

        // The happy path sets the clock to the seeded instant, Trusted.
        assert_eq!(
            h.wall_time_set(
                &ctx,
                0x3000,
                Time64::WIRE_LEN,
                u32::from(WallTimeState::Trusted.as_u8())
            ),
            Ok(0)
        );

        // Now get reflects the set instant and state. The seconds match
        // exactly; the few-ns monotonic elapsed only touches the nanos.
        let wrote = h.wall_time_get(&ctx, 0x1000, 64).expect("reading written");
        assert_eq!(wrote, WallClockReading::WIRE_LEN as u64);
        let guard = aspaces.read();
        let (_s, pm) = guard.resolve(SecTaskId(9)).expect("aspace present");
        let bytes = read_server_page(pm, 1, WallClockReading::WIRE_LEN);
        let r = WallClockReading::from_bytes(&bytes).expect("valid reading");
        assert_eq!(r.state(), WallTimeState::Trusted);
        assert_eq!(r.time().secs(), 1_700_000_000);
        assert!(r.time().subsec_nanos() < 1_000);
    }

    /// `boot_id_get` fails closed with `BufferTooSmall` for a buffer shorter
    /// than `BOOT_ID_LEN` and with `EntropyNotReady` while the boot id is
    /// unset — both *before* any address-space access, and even when a real id
    /// is installed (the short-buffer rejection is unconditional). Once a
    /// `BootId` is installed and the buffer is large enough the 16 bytes are
    /// copied out to the caller and the byte count returned.
    #[test]
    fn boot_id_get_fails_closed_then_copies_out_the_minted_id() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // A writable caller page for the copy-out, registered for task 2.
        let (space, physmap) = send_aspace(MapFlags::WRITE | MapFlags::USER, &[]);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };

        // Unset (default): a short buffer is rejected before anything else,
        // and a large-enough buffer fails closed `EntropyNotReady` rather than
        // ever emitting the all-zero sentinel.
        let unset = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        assert_eq!(
            unset.boot_id_get(&ctx, 0x1000, 0),
            Err(Errno::BufferTooSmall)
        );
        assert_eq!(
            unset.boot_id_get(&ctx, 0x1000, BOOT_ID_LEN),
            Err(Errno::EntropyNotReady)
        );

        // With a real id installed: a short buffer is still rejected, and a
        // large-enough one copies the 16 bytes out and returns the count.
        let id = BootId::from_raw([0x5A; BOOT_ID_LEN]);
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_boot_id(id);
        assert_eq!(
            h.boot_id_get(&ctx, 0x1000, BOOT_ID_LEN - 1),
            Err(Errno::BufferTooSmall)
        );
        assert_eq!(
            h.boot_id_get(&ctx, 0x1000, BOOT_ID_LEN),
            Ok(BOOT_ID_LEN as u64)
        );
    }

    /// `boot_facts_get` fails closed with `BufferTooSmall` for a buffer
    /// shorter than the wire length and with `NotImplemented` while no boot
    /// path installed the facts — both *before* any address-space access.
    /// Once facts are installed and the buffer is large enough, the record
    /// is copied out and decodes back to the installed values.
    #[test]
    fn boot_facts_get_fails_closed_then_copies_out_the_installed_facts() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // A writable caller page (page 1 = `0x1000`) for the copy-out.
        let (space, physmap) = server_aspace(&[]);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };

        // Uninstalled (default): a short buffer is rejected before anything
        // else, and a large-enough buffer fails closed `NotImplemented`
        // rather than ever fabricating a machine shape.
        let unset = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        assert_eq!(
            unset.boot_facts_get(&ctx, 0x1000, 0),
            Err(Errno::BufferTooSmall)
        );
        assert_eq!(
            unset.boot_facts_get(&ctx, 0x1000, BootFacts::WIRE_LEN),
            Err(Errno::NotImplemented)
        );

        // With facts installed: a short buffer is still rejected, and a
        // large-enough one copies the record out; it decodes back exactly.
        let facts = BootFacts {
            arch: rustos_abi::Arch::Aarch64,
            cpu_count: 4,
            memory_bytes: 8 * 1024 * 1024 * 1024,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_boot_facts(facts);
        assert_eq!(
            h.boot_facts_get(&ctx, 0x1000, BootFacts::WIRE_LEN - 1),
            Err(Errno::BufferTooSmall)
        );
        assert_eq!(
            h.boot_facts_get(&ctx, 0x1000, BootFacts::WIRE_LEN),
            Ok(BootFacts::WIRE_LEN as u64)
        );
        let guard = aspaces.read();
        let (_s, pm) = guard.resolve(SecTaskId(2)).expect("aspace present");
        let bytes = read_server_page(pm, 1, BootFacts::WIRE_LEN);
        assert_eq!(BootFacts::from_bytes(&bytes), Ok(facts));
    }

    /// `terminal_size` copies out the grid of a console whose geometry the
    /// kernel knows (a framebuffer text console), and fails closed for a
    /// console with no known geometry (a UART) rather than fabricating one,
    /// for a short buffer, and for a descriptor that is not an open stream.
    #[test]
    fn terminal_size_reports_a_known_console_grid_and_fails_closed_otherwise() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // A writable caller page (page 1 = `0x1000`) for the copy-out.
        let (space, physmap) = server_aspace(&[]);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };

        let grid = rustos_abi::TerminalSize::new(45, 100).expect("valid grid");
        // Console 0 is a framebuffer text console reporting a known grid;
        // console 1 is a UART that reports no geometry (a `RecordingConsole`,
        // which takes the trait's `geometry() -> None` default).
        let video: &'static GridConsole = Box::leak(Box::new(GridConsole(grid)));
        let uart: &'static RecordingConsole = Box::leak(Box::new(RecordingConsole::new()));
        let consoles: &'static [ConsoleDevice] = Box::leak(Box::new([
            ConsoleDevice::new(video, &crate::console::NULL_CONSOLE_READ),
            ConsoleDevice::new(uart, &crate::console::NULL_CONSOLE_READ),
        ]));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_consoles(consoles);

        // Attached to console 0 (the display): the known grid is copied out.
        aspaces
            .write()
            .set_streams(SecTaskId(2), DescriptorTable::standard_on(0));
        assert_eq!(
            h.terminal_size(&ctx, STDOUT, 0x1000, TERMINAL_SIZE_WIRE_LEN),
            Ok(TERMINAL_SIZE_WIRE_LEN as u64)
        );
        {
            let guard = aspaces.read();
            let (_s, pm) = guard.resolve(SecTaskId(2)).expect("aspace present");
            let bytes = read_server_page(pm, 1, TERMINAL_SIZE_WIRE_LEN);
            assert_eq!(rustos_abi::TerminalSize::from_bytes(&bytes), Ok(grid));
        }

        // A short buffer fails closed rather than truncating the reading.
        assert_eq!(
            h.terminal_size(&ctx, STDOUT, 0x1000, TERMINAL_SIZE_WIRE_LEN - 1),
            Err(Errno::BufferTooSmall)
        );

        // Attached to console 1 (the UART): the kernel does not know its size,
        // so it fails closed rather than fabricating one.
        aspaces
            .write()
            .set_streams(SecTaskId(2), DescriptorTable::standard_on(1));
        assert_eq!(
            h.terminal_size(&ctx, STDOUT, 0x1000, TERMINAL_SIZE_WIRE_LEN),
            Err(Errno::NotImplemented)
        );

        // A descriptor that is not an open stream (an fd beyond the standard
        // set) fails closed `NotFound`.
        aspaces
            .write()
            .set_streams(SecTaskId(2), DescriptorTable::standard_on(0));
        assert_eq!(
            h.terminal_size(&ctx, 9, 0x1000, TERMINAL_SIZE_WIRE_LEN),
            Err(Errno::NotFound)
        );
    }

    // --- filesystem syscalls (P-A) ----------------

    // `DirEntry`, `FileStat`, and `OpenFlags` are already in scope through
    // `use super::*`; only `FileKind` is additionally needed here.
    use rustos_abi::FileKind;

    /// A recording [`FilesystemService`] double: it logs each call's
    /// attested uid and arguments (so a test can prove the handler attested
    /// the caller and forwarded the right path/offset/append), serves
    /// canned read/readdir/stat results, and can be set to fail a chosen op
    /// closed. Recording goes through a [`std::sync::Mutex`] because the
    /// service must be `Send + Sync`.
    struct RecordingFs {
        read_data: Vec<u8>,
        entries: Vec<crate::fs::ReaddirEntry>,
        stat: FileStat,
        open_err: Option<Errno>,
        log: std::sync::Mutex<Vec<String>>,
    }

    impl RecordingFs {
        fn new() -> Self {
            Self {
                read_data: Vec::new(),
                entries: Vec::new(),
                stat: FileStat {
                    kind: FileKind::Regular,
                    size: 0,
                    allocated: 0,
                    mode: 0o644,
                    uid: 1000,
                    gid: 1000,
                },
                open_err: None,
                log: std::sync::Mutex::new(Vec::new()),
            }
        }

        fn record(&self, entry: alloc::string::String) {
            self.log.lock().expect("uncontended").push(entry);
        }

        fn calls(&self) -> Vec<String> {
            self.log.lock().expect("uncontended").clone()
        }
    }

    impl FilesystemService for RecordingFs {
        fn open(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            flags: OpenFlags,
        ) -> Result<(), Errno> {
            self.record(alloc::format!(
                "open uid={uid} path={path} flags={}",
                flags.bits()
            ));
            match self.open_err {
                Some(err) => Err(err),
                None => Ok(()),
            }
        }

        fn read(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            offset: u64,
            buf: &mut [u8],
        ) -> Result<usize, Errno> {
            self.record(alloc::format!(
                "read uid={uid} path={path} off={offset} len={}",
                buf.len()
            ));
            let n = self.read_data.len().min(buf.len());
            buf[..n].copy_from_slice(&self.read_data[..n]);
            Ok(n)
        }

        fn write(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            offset: u64,
            append: bool,
            data: &[u8],
        ) -> Result<usize, Errno> {
            self.record(alloc::format!(
                "write uid={uid} path={path} off={offset} append={append} data={data:?}"
            ));
            Ok(data.len())
        }

        fn readdir(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
        ) -> Result<Vec<crate::fs::ReaddirEntry>, Errno> {
            self.record(alloc::format!("readdir uid={uid} path={path}"));
            Ok(self.entries.clone())
        }

        fn stat(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
        ) -> Result<FileStat, Errno> {
            self.record(alloc::format!("stat uid={uid} path={path}"));
            Ok(self.stat)
        }

        fn truncate(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            size: u64,
        ) -> Result<(), Errno> {
            self.record(alloc::format!("truncate uid={uid} path={path} size={size}"));
            Ok(())
        }

        fn sync(&self, uid: u32, _caps: &dyn rustos_abi::CapabilityQuery) -> Result<(), Errno> {
            self.record(alloc::format!("sync uid={uid}"));
            Ok(())
        }

        fn mkdir(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
        ) -> Result<(), Errno> {
            self.record(alloc::format!("mkdir uid={uid} path={path}"));
            Ok(())
        }

        fn unlink(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            _flags: UnlinkFlags,
        ) -> Result<(), Errno> {
            self.record(alloc::format!("unlink uid={uid} path={path}"));
            Ok(())
        }

        fn rename(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            src: &str,
            dst: &str,
        ) -> Result<(), Errno> {
            self.record(alloc::format!("rename uid={uid} src={src} dst={dst}"));
            Ok(())
        }

        fn set_mode(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            mode: u32,
        ) -> Result<(), Errno> {
            self.record(alloc::format!(
                "set_mode uid={uid} path={path} mode={mode:o}"
            ));
            Ok(())
        }

        // The attribute methods record the marshalled call and serve one
        // canned attribute (`user.demo` = `v1`), so the handler tests can
        // assert both the copy-in wiring and the copy-out path.
        fn attr_get(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            key: &[u8],
            value_out: &mut [u8],
        ) -> Result<usize, Errno> {
            self.record(alloc::format!(
                "attr_get uid={uid} path={path} key={}",
                core::str::from_utf8(key).unwrap_or("<bad>")
            ));
            if key != b"user.demo" {
                return Err(Errno::NoData);
            }
            let value = b"v1";
            let out = value_out
                .get_mut(..value.len())
                .ok_or(Errno::BufferTooSmall)?;
            out.copy_from_slice(value);
            Ok(value.len())
        }

        fn attr_set(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            key: &[u8],
            value: &[u8],
        ) -> Result<(), Errno> {
            self.record(alloc::format!(
                "attr_set uid={uid} path={path} key={} value_len={}",
                core::str::from_utf8(key).unwrap_or("<bad>"),
                value.len()
            ));
            Ok(())
        }

        fn attr_list(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            index: u64,
            key_out: &mut [u8],
        ) -> Result<Option<usize>, Errno> {
            self.record(alloc::format!(
                "attr_list uid={uid} path={path} index={index}"
            ));
            if index != 0 {
                return Ok(None);
            }
            let key = b"user.demo";
            let out = key_out.get_mut(..key.len()).ok_or(Errno::BufferTooSmall)?;
            out.copy_from_slice(key);
            Ok(Some(key.len()))
        }

        fn attr_remove(
            &self,
            uid: u32,
            _caps: &dyn rustos_abi::CapabilityQuery,
            path: &str,
            key: &[u8],
        ) -> Result<(), Errno> {
            self.record(alloc::format!(
                "attr_remove uid={uid} path={path} key={}",
                core::str::from_utf8(key).unwrap_or("<bad>")
            ));
            Ok(())
        }
    }

    /// `fs_open` resolves+authorises through the service under the caller's
    /// attested uid and records a descriptor at/above the standard streams.
    #[test]
    fn fs_open_attests_the_caller_and_allocates_a_descriptor() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, b"/System/Logs/a");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let fs: &'static RecordingFs = Box::leak(Box::new(RecordingFs::new()));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_filesystem(fs);

        let fd = h
            .fs_open(&ctx, 0x1000, "/System/Logs/a".len(), OpenFlags::READ)
            .expect("open succeeds");
        assert_eq!(fd, 4, "the first descriptor follows the standard streams");
        assert_eq!(
            fs.calls(),
            alloc::vec![alloc::string::String::from(
                "open uid=1000 path=/System/Logs/a flags=1"
            )],
            "the handler attested the caller's uid and forwarded the path/flags"
        );
    }

    /// With no filesystem wired the handler holds `NULL_FILESYSTEM` and
    /// `fs_open` fails closed with `NotImplemented`.
    #[test]
    fn fs_open_without_filesystem_is_not_implemented() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, b"/Storage/x");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );
        assert_eq!(
            h.fs_open(&ctx, 0x1000, "/Storage/x".len(), OpenFlags::READ),
            Err(Errno::NotImplemented)
        );
        // No descriptor was recorded for the caller.
        assert_eq!(aspaces.read().open_file_entry(SecTaskId(2), 4), None);
    }

    /// A refused open (e.g. exclusive-create clash) yields no descriptor.
    #[test]
    fn fs_open_refused_records_no_descriptor() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, b"/Storage/x");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let mut mock = RecordingFs::new();
        mock.open_err = Some(Errno::AlreadyExists);
        let fs: &'static RecordingFs = Box::leak(Box::new(mock));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_filesystem(fs);
        assert_eq!(
            h.fs_open(&ctx, 0x1000, "/Storage/x".len(), OpenFlags::READ),
            Err(Errno::AlreadyExists)
        );
        assert_eq!(aspaces.read().open_file_entry(SecTaskId(2), 4), None);
    }

    /// `fs_read` re-authorises through the service and copies the read bytes
    /// out to the caller; an unknown fd and a write-only handle fail closed.
    #[test]
    fn fs_read_copies_bytes_out_and_enforces_the_handle() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) =
            send_aspace(MapFlags::READ | MapFlags::WRITE | MapFlags::USER, b"/f");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let mut mock = RecordingFs::new();
        mock.read_data = b"hello".to_vec();
        let fs: &'static RecordingFs = Box::leak(Box::new(mock));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_filesystem(fs);

        // An unknown descriptor fails closed before the service is touched.
        assert_eq!(h.fs_read(&ctx, 99, 0, 0x1000, 5), Err(Errno::NotFound));

        let fd = u32::try_from(
            h.fs_open(&ctx, 0x1000, "/f".len(), OpenFlags::READ)
                .expect("open"),
        )
        .unwrap();
        let n = h.fs_read(&ctx, fd, 0, 0x1000, 5).expect("read");
        assert_eq!(n, 5);
        let delivered = h
            .with_caller_aspace(&ctx, |space, physmap| {
                let mut buf = alloc::vec![0u8; 5];
                copy_in(space, physmap, VirtAddr::new(0x1000), &mut buf).expect("readable");
                buf
            })
            .expect("caller space");
        assert_eq!(delivered.as_slice(), b"hello");

        // A handle opened without READ refuses fs_read.
        let wo = u32::try_from(
            h.fs_open(&ctx, 0x1000, "/f".len(), OpenFlags::WRITE)
                .expect("open write-only"),
        )
        .unwrap();
        // Re-seed the path page is unnecessary; the handle keeps its own path.
        assert_eq!(
            h.fs_read(&ctx, wo, 0, 0x1000, 5),
            Err(Errno::PermissionDenied)
        );
    }

    /// `fs_write` stages the caller's bytes in and forwards them, honouring
    /// the append posture; a read-only handle is refused.
    #[test]
    fn fs_write_forwards_bytes_and_honours_append() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) =
            send_aspace(MapFlags::READ | MapFlags::WRITE | MapFlags::USER, b"AB");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let fs: &'static RecordingFs = Box::leak(Box::new(RecordingFs::new()));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_filesystem(fs);

        // Open append+write; page 0x1000 holds the two payload bytes "AB".
        let fd = u32::try_from(
            h.fs_open(&ctx, 0x1000, 2, OpenFlags::WRITE.union(OpenFlags::APPEND))
                .expect("open append"),
        )
        .unwrap();
        // The path was 2 bytes ("AB" doubles as the path and the payload here).
        let n = h.fs_write(&ctx, fd, 0x999, 0x1000, 2).expect("write");
        assert_eq!(n, 2);
        let calls = fs.calls();
        assert!(
            calls.iter().any(|c| c.contains("write uid=1000")
                && c.contains("append=true")
                && c.contains("data=[65, 66]")),
            "the append write forwarded the staged bytes: {calls:?}"
        );

        // A read-only handle refuses fs_write.
        let ro = u32::try_from(
            h.fs_open(&ctx, 0x1000, 2, OpenFlags::READ)
                .expect("open ro"),
        )
        .unwrap();
        assert_eq!(
            h.fs_write(&ctx, ro, 0, 0x1000, 2),
            Err(Errno::PermissionDenied)
        );
    }

    /// `fs_readdir` packs the service's entries into the `DirEntry` stream;
    /// an undersized buffer fails closed without truncating.
    #[test]
    fn fs_readdir_packs_entries_and_rejects_a_small_buffer() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) =
            send_aspace(MapFlags::READ | MapFlags::WRITE | MapFlags::USER, b"/d");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let mut mock = RecordingFs::new();
        mock.entries = alloc::vec![
            crate::fs::ReaddirEntry {
                kind: FileKind::Directory,
                size: 0,
                allocated: 4096,
                modified: Time64::from_secs(1_111),
                name: alloc::string::String::from("Logs"),
            },
            crate::fs::ReaddirEntry {
                kind: FileKind::Regular,
                size: 17,
                allocated: 512,
                modified: Time64::from_secs(2_222),
                name: alloc::string::String::from("motd"),
            },
        ];
        let fs: &'static RecordingFs = Box::leak(Box::new(mock));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_filesystem(fs);

        let fd = u32::try_from(
            h.fs_open(&ctx, 0x1000, "/d".len(), OpenFlags::DIRECTORY)
                .expect("open dir"),
        )
        .unwrap();
        // Two records: (32 + 4) + (32 + 4) = 72 bytes.
        let total = usize::try_from(h.fs_readdir(&ctx, fd, 0x1000, 96).expect("readdir")).unwrap();
        assert_eq!(total, 72);
        let stream = h
            .with_caller_aspace(&ctx, |space, physmap| {
                let mut buf = alloc::vec![0u8; total];
                copy_in(space, physmap, VirtAddr::new(0x1000), &mut buf).expect("readable");
                buf
            })
            .expect("caller space");
        let (first, used) = DirEntry::decode(&stream).expect("first entry");
        assert_eq!(first.kind, FileKind::Directory);
        assert_eq!(first.size, 0);
        assert_eq!(first.allocated, 4096);
        assert_eq!(first.modified, Time64::from_secs(1_111));
        assert_eq!(first.name, b"Logs");
        let (second, _) = DirEntry::decode(&stream[used..]).expect("second entry");
        assert_eq!(second.size, 17);
        assert_eq!(second.allocated, 512);
        assert_eq!(second.modified, Time64::from_secs(2_222));
        assert_eq!(second.name, b"motd");

        // A buffer too small for the whole listing fails closed.
        assert_eq!(
            h.fs_readdir(&ctx, fd, 0x1000, 4),
            Err(Errno::BufferTooSmall)
        );
    }

    /// `fs_stat` writes the service's `FileStat` to the caller; `fs_close`
    /// frees the descriptor and a double close fails closed.
    #[test]
    fn fs_stat_writes_metadata_and_close_frees_the_descriptor() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) =
            send_aspace(MapFlags::READ | MapFlags::WRITE | MapFlags::USER, b"/f");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let mut mock = RecordingFs::new();
        mock.stat = FileStat {
            kind: FileKind::Regular,
            size: 0x1234,
            allocated: 0x2000,
            mode: 0o640,
            uid: 1000,
            gid: 1000,
        };
        let fs: &'static RecordingFs = Box::leak(Box::new(mock));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_filesystem(fs);

        let fd = u32::try_from(
            h.fs_open(&ctx, 0x1000, "/f".len(), OpenFlags::READ)
                .expect("open"),
        )
        .unwrap();
        let n = usize::try_from(
            h.fs_stat(&ctx, fd, 0x1000, FileStat::WIRE_LEN)
                .expect("stat"),
        )
        .unwrap();
        assert_eq!(n, FileStat::WIRE_LEN);
        let decoded = h
            .with_caller_aspace(&ctx, |space, physmap| {
                let mut buf = alloc::vec![0u8; FileStat::WIRE_LEN];
                copy_in(space, physmap, VirtAddr::new(0x1000), &mut buf).expect("readable");
                FileStat::decode(&buf).expect("valid stat")
            })
            .expect("caller space");
        assert_eq!(decoded.size, 0x1234);
        assert_eq!(decoded.mode, 0o640);

        // An undersized stat buffer fails closed.
        assert_eq!(
            h.fs_stat(&ctx, fd, 0x1000, FileStat::WIRE_LEN - 1),
            Err(Errno::BufferTooSmall)
        );

        // Close frees the descriptor; a second close fails closed.
        assert_eq!(h.fs_close(&ctx, fd), Ok(0));
        assert_eq!(h.fs_close(&ctx, fd), Err(Errno::NotFound));
        assert_eq!(
            h.fs_stat(&ctx, fd, 0x1000, FileStat::WIRE_LEN),
            Err(Errno::NotFound)
        );
    }

    /// `fs_chdir` re-authorises the target as a searchable directory through
    /// the VFS and, only on success, records it as the caller's new working
    /// directory (against which later relative paths resolve).
    #[test]
    fn fs_chdir_authorises_a_directory_and_sets_the_cwd() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, b"/Users/bob");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let fs: &'static RecordingFs = Box::leak(Box::new(RecordingFs::new()));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_filesystem(fs);

        assert_eq!(h.fs_chdir(&ctx, 0x1000, "/Users/bob".len()), Ok(0));
        assert_eq!(aspaces.read().cwd(SecTaskId(2)), "/Users/bob");
        // The target was re-authorised as a directory (resolve-only, the
        // `DIRECTORY` flag, neither read nor write).
        assert_eq!(
            fs.calls(),
            alloc::vec![alloc::format!(
                "open uid=1000 path=/Users/bob flags={}",
                OpenFlags::DIRECTORY.bits()
            )]
        );
    }

    /// A refused `fs_chdir` (the target is not a searchable directory) leaves
    /// the working directory unchanged (fail closed).
    #[test]
    fn fs_chdir_on_a_refused_target_leaves_the_cwd_unchanged() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, b"/Storage/x");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("registration succeeds");
        // A directory the caller is already sitting in.
        aspaces
            .write()
            .set_cwd(SecTaskId(2), alloc::string::String::from("/Users"));
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[CapabilityId::FS_ACCESS], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let mut mock = RecordingFs::new();
        mock.open_err = Some(Errno::PermissionDenied);
        let fs: &'static RecordingFs = Box::leak(Box::new(mock));
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        )
        .with_filesystem(fs);

        assert_eq!(
            h.fs_chdir(&ctx, 0x1000, "/Storage/x".len()),
            Err(Errno::PermissionDenied)
        );
        // The refused chdir never reached `set_cwd`.
        assert_eq!(aspaces.read().cwd(SecTaskId(2)), "/Users");
    }

